window.FINAL_BANK={"1":{"title":"Week 1 — Foundations: Genetics & Cellular Biology","slides":{"Genetics":"17–20","Chromosomal Disorders":"21–22","Inheritance":"23–24","Epigenetics":"25","Cellular Adaptation":"30","Cell Injury":"31","Fluids & Electrolytes":"33","Acid-Base":"34–36"},"questions":[{"q":"DNA replication is described as 'semi-conservative.' What does this mean?","a":["Each new DNA molecule has one original (parental) strand and one newly made strand","Half the DNA is destroyed and rebuilt each cycle","Only half the genome is copied before division","Two entirely new strands are made and the original is discarded"],"c":0,"t":"Genetics","fb":"Semi-conservative = each daughter molecule keeps one parental strand paired with one new strand.","d":"m"},{"q":"In which cell location and direction does transcription produce mRNA?","a":["In the nucleus; RNA polymerase reads the template 3'→5'","At the ribosome; reading 5'→3'","In the mitochondria; using tRNA","In the cytoplasm; reading 5'→3'"],"c":0,"t":"Genetics","fb":"Transcription: DNA template → mRNA in the nucleus; RNA polymerase reads the template strand 3'→5'.","d":"m"},{"q":"Where does translation occur, and what delivers amino acids?","a":["At the ribosome; tRNA delivers amino acids by codon","In the nucleus; mRNA delivers amino acids","At the ribosome; DNA delivers amino acids","In the nucleolus; rRNA delivers amino acids"],"c":0,"t":"Genetics","fb":"Translation builds protein at the ribosome; tRNA brings the matching amino acid for each codon.","d":"m"},{"q":"How many chromosomes are in a normal human somatic (body) cell?","a":["46 (diploid)","23 (haploid)","92","23 pairs of alleles"],"c":0,"t":"Genetics","fb":"Somatic cells are diploid with 46 chromosomes; gametes are haploid with 23.","d":"m"},{"q":"Why do human gametes contain only 23 chromosomes?","a":["They are produced by meiosis, which halves the chromosome number","They are produced by mitosis","Half the chromosomes degrade after fertilization","Gametes lose chromosomes during transcription"],"c":0,"t":"Genetics","fb":"Meiosis reduces the diploid number (46) to the haploid number (23) in gametes.","d":"m"},{"q":"Place the molecular processes in the correct order (central dogma).","a":["Replication → Transcription → Translation","Transcription → Replication → Translation","Translation → Transcription → Replication","Replication → Translation → Transcription"],"c":0,"t":"Genetics","fb":"DNA copies itself (replication), is read into mRNA (transcription), then mRNA builds protein (translation).","d":"m"},{"q":"Select ALL that are types of point mutations.","a":["Silent","Missense","Nonsense","Frameshift"],"c":0,"t":"Genetics","fb":"Point mutations: silent, missense, nonsense. A frameshift results from insertions/deletions, not a single-base point change.","d":"m"},{"q":"A frameshift mutation is caused by:","a":["Insertion or deletion of bases that shifts the reading frame","A single base substitution that changes one amino acid","Duplication of an entire chromosome","Methylation of a promoter region"],"c":0,"t":"Genetics","fb":"Insertions or deletions (not in multiples of three) shift the reading frame downstream.","d":"m"},{"q":"Select ALL recognized causes of mutations.","a":["Spontaneous replication errors","Radiation","Chemical mutagens","Viral integration into the genome"],"c":0,"t":"Genetics","fb":"All listed: spontaneous error, radiation, chemicals, and viral integration can all cause mutations.","d":"m"},{"q":"Down syndrome results from which chromosomal abnormality?","a":["Trisomy 21","Monosomy 21","Trisomy 13","45,X"],"c":0,"t":"Chromosomal Disorders","fb":"Down syndrome = trisomy 21 (an autosomal aneuploidy).","d":"m"},{"q":"A short-statured female with gonadal dysgenesis and lymphedema most likely has which karyotype?","a":["45,X (Turner syndrome)","47,XXY (Klinefelter)","47,XXX","Trisomy 13"],"c":0,"t":"Chromosomal Disorders","fb":"Turner syndrome = 45,X monosomy: short stature, gonadal dysgenesis, lymphedema.","d":"m"},{"q":"A tall male with hypogonadism, gynecomastia, and infertility most likely has:","a":["47,XXY (Klinefelter syndrome)","45,X (Turner)","Trisomy 21","Trisomy 13"],"c":0,"t":"Chromosomal Disorders","fb":"Klinefelter = 47,XXY: tall stature, hypogonadism, gynecomastia, infertility.","d":"m"},{"q":"Patau syndrome corresponds to which trisomy, and a hallmark feature is:","a":["Trisomy 13; cleft lip/palate and severe CNS malformation","Trisomy 21; characteristic facies","Trisomy 18; rocker-bottom feet only","Trisomy X; usually asymptomatic"],"c":0,"t":"Chromosomal Disorders","fb":"Patau = trisomy 13 with cleft lip/palate, polydactyly, and severe CNS malformation.","d":"m"},{"q":"'Monosomy' means:","a":["One chromosome of a pair is missing","One extra chromosome is present","An extra full set of chromosomes","A piece of a chromosome is inverted"],"c":0,"t":"Chromosomal Disorders","fb":"Monosomy = a missing chromosome (e.g., 45,X). Trisomy = one extra.","d":"m"},{"q":"Select ALL STRUCTURAL chromosome abnormalities (not numerical).","a":["Deletion","Translocation","Inversion","Trisomy"],"c":0,"t":"Chromosomal Disorders","fb":"Structural: deletion, duplication, inversion, translocation. Trisomy/monosomy are numerical (aneuploidy).","d":"m"},{"q":"'Mosaicism' refers to:","a":["An individual with two or more genetically different cell lines","Two different alleles at one locus","An extra set of every chromosome","A maternally inherited mitochondrial trait"],"c":0,"t":"Chromosomal Disorders","fb":"Mosaicism = mixed cell lines; the phenotype depends on the ratio of affected cells.","d":"m"},{"q":"A 35-year-old asks why her risk of a child with Down syndrome is higher than a 25-year-old's. Best explanation?","a":["Aging oocytes spend longer arrested in meiosis, making the spindle more error-prone","Older mothers have more environmental DNA damage during pregnancy","Down syndrome is autosomal recessive and older parents are carriers","Older fathers produce sperm with more chromosome errors"],"c":0,"t":"Chromosomal Disorders","fb":"Prolonged meiotic arrest in aging oocytes increases nondisjunction risk.","d":"m"},{"q":"Autosomal dominant inheritance is best described by:","a":["One affected parent confers ~50% risk; both sexes equally affected","Two carrier parents confer 25% risk","Mostly males affected, females are carriers","Maternal transmission to all offspring"],"c":0,"t":"Inheritance","fb":"AD: one affected parent → 50% of children affected; examples include Huntington and Marfan.","d":"m"},{"q":"Which conditions are classic AUTOSOMAL RECESSIVE disorders? Select all that apply.","a":["Cystic fibrosis","Sickle cell anemia","Phenylketonuria (PKU)","Huntington disease"],"c":0,"t":"Inheritance","fb":"CF, sickle cell, and PKU are autosomal recessive. Huntington is autosomal dominant.","d":"m"},{"q":"X-linked recessive disorders such as hemophilia A and Duchenne muscular dystrophy:","a":["Mostly affect males, with females typically being carriers","Affect females more than males","Show male-to-male transmission","Are transmitted only by the father"],"c":0,"t":"Inheritance","fb":"X-linked recessive: males (one X) are usually affected; carrier females pass it on.","d":"m"},{"q":"Mitochondrial inheritance is characterized by:","a":["Maternal transmission to all offspring; affects high-energy tissues","Paternal transmission only","50% risk from one affected parent","Carrier females and affected males"],"c":0,"t":"Inheritance","fb":"Mitochondria are maternally inherited, so all children of an affected mother can be affected (e.g., MELAS, LHON).","d":"m"},{"q":"A recessive allele is expressed only when the individual is:","a":["Homozygous for that allele","Heterozygous","A carrier","Hemizygous on an autosome"],"c":0,"t":"Inheritance","fb":"Recessive traits require two copies (homozygous) to be expressed.","d":"m"},{"q":"Penetrance and expressivity differ how?","a":["Penetrance = % of carriers who express the trait; expressivity = how strongly it is expressed","Penetrance = severity; expressivity = frequency","They are synonyms","Penetrance applies only to recessive traits"],"c":0,"t":"Inheritance","fb":"Penetrance is whether the trait shows at all; expressivity is how strongly it shows.","d":"m"},{"q":"Genotype vs. phenotype: which statement is correct?","a":["Genotype = the alleles carried; phenotype = the observable expression","Genotype = observable traits; phenotype = the alleles","They mean the same thing","Phenotype is always dominant"],"c":0,"t":"Inheritance","fb":"Genotype is the genetic makeup; phenotype is what is expressed/observed.","d":"m"},{"q":"Which inheritance pattern shows NO male-to-male transmission?","a":["X-linked","Autosomal dominant","Autosomal recessive","Mitochondrial only through fathers"],"c":0,"t":"Inheritance","fb":"Fathers pass their Y (not X) to sons, so X-linked traits never go father→son.","d":"m"},{"q":"Epigenetics is best defined as:","a":["Heritable changes in gene EXPRESSION that do not alter the DNA sequence","Permanent changes to the DNA base sequence","Random new mutations after birth","Loss of a whole chromosome"],"c":0,"t":"Epigenetics","fb":"Epigenetic changes (methylation, histone modification, non-coding RNA) alter expression without changing the sequence.","d":"m"},{"q":"Identical twins share DNA, yet only one develops type 2 diabetes at 45. Best explanation?","a":["Different environmental exposures produced different epigenetic marks altering gene expression","One twin's DNA mutated after birth","One twin inherited a new gene","They are not truly identical"],"c":0,"t":"Epigenetics","fb":"Discordance in identical twins often reflects epigenetic differences from environment/lifestyle.","d":"m"},{"q":"Select ALL recognized epigenetic mechanisms.","a":["DNA methylation","Histone modification","Non-coding RNA regulation","Frameshift mutation"],"c":0,"t":"Epigenetics","fb":"Epigenetic mechanisms: methylation, histone modification, non-coding RNA. A frameshift is a sequence mutation.","d":"m"},{"q":"Atrophy is defined as:","a":["A decrease in cell size","An increase in cell size","An increase in cell number","Replacement of one cell type by another"],"c":0,"t":"Cellular Adaptation","fb":"Atrophy = shrinkage in cell size (e.g., disuse muscle atrophy).","d":"m"},{"q":"Long-standing hypertension causes thickening of the left ventricular wall. This adaptation is:","a":["Hypertrophy","Hyperplasia","Metaplasia","Atrophy"],"c":0,"t":"Cellular Adaptation","fb":"Increased workload → increased cell SIZE = hypertrophy (cardiac myocytes don't divide).","d":"m"},{"q":"Hyperplasia refers to:","a":["An increase in the NUMBER of cells","An increase in cell size","Abnormal cell organization","One mature cell type replacing another"],"c":0,"t":"Cellular Adaptation","fb":"Hyperplasia = more cells (e.g., endometrial hyperplasia).","d":"m"},{"q":"Barrett esophagus (squamous → columnar epithelium) is an example of:","a":["Metaplasia","Dysplasia","Hyperplasia","Atrophy"],"c":0,"t":"Cellular Adaptation","fb":"Metaplasia = one mature cell type is replaced by another, often in response to chronic irritation.","d":"m"},{"q":"Cervical 'dysplasia' on a Pap smear indicates:","a":["Abnormal cell size, shape, or organization","A decrease in cell number","Replacement by another mature tissue","Normal physiologic adaptation"],"c":0,"t":"Cellular Adaptation","fb":"Dysplasia = disordered growth with abnormal size/shape/organization; it can be a precursor to malignancy.","d":"m"},{"q":"Match adaptations to mechanism — select ALL that involve a change in cell SIZE (not number).","a":["Atrophy","Hypertrophy","Hyperplasia","Metaplasia"],"c":0,"t":"Cellular Adaptation","fb":"Atrophy (smaller) and hypertrophy (larger) change cell SIZE; hyperplasia changes NUMBER; metaplasia changes TYPE.","d":"m"},{"q":"What is the MOST common cause of cellular injury?","a":["Hypoxia (inadequate O2 delivery)","Radiation","Bacterial toxins","Genetic mutation"],"c":0,"t":"Cell Injury","fb":"Hypoxia is the most common cause of cell injury; early injury is reversible, sustained ischemia is not.","d":"m"},{"q":"Which statement correctly contrasts necrosis and apoptosis?","a":["Necrosis is uncontrolled and inflammatory; apoptosis is programmed and non-inflammatory","Necrosis is programmed; apoptosis is pathologic","Both are always pathologic","Apoptosis always triggers inflammation"],"c":0,"t":"Cell Injury","fb":"Necrosis = uncontrolled, inflammatory cell death; apoptosis = programmed, 'clean,' non-inflammatory.","d":"m"},{"q":"Select ALL recognized types of necrosis.","a":["Coagulative","Liquefactive","Caseous","Apoptotic"],"c":0,"t":"Cell Injury","fb":"Necrosis types include coagulative, liquefactive, caseous, fat, and fibrinoid. Apoptosis is a separate, programmed process.","d":"m"},{"q":"Regarding reversibility of cell injury from ischemia:","a":["Injury is reversible early but becomes irreversible after sustained ischemia","All ischemic injury is immediately irreversible","Ischemic injury is always reversible","Reversibility depends only on cell type, not duration"],"c":0,"t":"Cell Injury","fb":"Time matters: early hypoxic injury can recover; prolonged ischemia causes irreversible (often necrotic) damage.","d":"m"},{"q":"Apoptosis is best characterized as:","a":["Programmed, physiologic, non-inflammatory cell death","Uncontrolled cell rupture with inflammation","Always a sign of disease","Caused only by hypoxia"],"c":0,"t":"Cell Injury","fb":"Apoptosis is the body's controlled, energy-dependent removal of cells without inflammation.","d":"m"},{"q":"A patient with SIADH presents with confusion, nausea, and a seizure. The likely electrolyte disturbance is:","a":["Hyponatremia","Hypernatremia","Hyperkalemia","Hypercalcemia"],"c":0,"t":"Fluids & Electrolytes","fb":"SIADH causes water retention and dilutional hyponatremia → neuro symptoms (confusion, seizures).","d":"m"},{"q":"Peaked T waves and arrhythmias, often with renal failure or acidosis, suggest:","a":["Hyperkalemia","Hypokalemia","Hyponatremia","Hypocalcemia"],"c":0,"t":"Fluids & Electrolytes","fb":"Hyperkalemia → peaked T waves and arrhythmias; common in renal failure and acidosis.","d":"m"},{"q":"Muscle weakness with U waves on EKG, often from diuretics or GI losses, indicates:","a":["Hypokalemia","Hyperkalemia","Hypernatremia","Hypercalcemia"],"c":0,"t":"Fluids & Electrolytes","fb":"Hypokalemia → muscle weakness and U waves; common causes are diuretics and GI loss.","d":"m"},{"q":"'Stones, bones, groans, and moans' classically describes:","a":["Hypercalcemia","Hypocalcemia","Hyponatremia","Hyperkalemia","Hypokalemia"],"c":0,"t":"Fluids & Electrolytes","fb":"Hypercalcemia: kidney stones, bone pain, abdominal groans, psychiatric moans; causes include hyperparathyroidism and malignancy.","d":"m"},{"q":"Tetany with positive Chvostek and Trousseau signs indicates:","a":["Hypocalcemia","Hypercalcemia","Hypernatremia","Hyperkalemia"],"c":0,"t":"Fluids & Electrolytes","fb":"Hypocalcemia increases neuromuscular excitability → tetany, Chvostek/Trousseau signs.","d":"m"},{"q":"Hypernatremia most commonly presents with which signs and cause?","a":["Thirst, lethargy, irritability; from dehydration","Seizures; from water excess","U waves; from diuretics","Tetany; from low vitamin D"],"c":0,"t":"Fluids & Electrolytes","fb":"Hypernatremia (often from dehydration/water deficit) → thirst, lethargy, irritability.","d":"m"},{"q":"What is the normal arterial blood pH range?","a":["7.35–7.45","7.00–7.20","7.45–7.55","6.80–7.00"],"c":0,"t":"Acid-Base","fb":"Normal arterial pH is tightly held between 7.35 and 7.45.","d":"m"},{"q":"Using the ROME mnemonic, which is TRUE?","a":["Respiratory: pH and PaCO2 move in OPPOSITE directions; Metabolic: pH and HCO3 move EQUALLY (same direction)","Respiratory: pH and PaCO2 move together","Metabolic: pH and HCO3 move opposite","ROME applies only to respiratory disorders"],"c":0,"t":"Acid-Base","fb":"ROME: Respiratory Opposite, Metabolic Equal — a quick way to classify a primary disturbance.","d":"m"},{"q":"Arterial gas shows pH ↓, PaCO2 ↑, HCO3 ↑ (compensated). This is:","a":["Respiratory acidosis with renal (metabolic) compensation","Metabolic acidosis with respiratory compensation","Respiratory alkalosis","Metabolic alkalosis"],"c":0,"t":"Acid-Base","fb":"Low pH with high CO2 = respiratory acidosis; the kidneys retain HCO3 to compensate.","d":"m"},{"q":"A DKA patient has pH 7.22, PaCO2 26, HCO3 10. The disturbance is:","a":["Metabolic acidosis with respiratory compensation","Respiratory acidosis with metabolic compensation","Metabolic alkalosis","Respiratory alkalosis"],"c":0,"t":"Acid-Base","fb":"Low pH + low HCO3 = metabolic acidosis; the low PaCO2 (Kussmaul breathing) is respiratory compensation.","d":"m"},{"q":"Which statements about acid–base regulation are TRUE? Select all that apply.","a":["The respiratory system adjusts CO2 within minutes","The kidneys adjust HCO3 and H+ over hours to days","Bicarbonate is a major buffer system","The lungs are the slowest regulator"],"c":0,"t":"Acid-Base","fb":"Lungs respond fast (minutes, via CO2); kidneys respond slowly (hours–days, via HCO3/H+). Bicarbonate is a key buffer.","d":"m"},{"q":"Metabolic alkalosis shows which primary pattern?","a":["pH ↑ with HCO3 ↑","pH ↓ with HCO3 ↓","pH ↑ with PaCO2 ↑ as the primary change","pH ↓ with PaCO2 ↑"],"c":0,"t":"Acid-Base","fb":"Metabolic alkalosis = high pH driven by high HCO3; respiratory compensation hypoventilates to raise CO2.","d":"m"},{"q":"What does DNA stand for?","a":["Deoxyribonucleic acid","Dual nuclear acid","Dynamic nucleotide array","Dense nuclear antigen"],"c":0,"t":"Genetics","fb":"DNA = deoxyribonucleic acid, the molecule that carries genetic information.","d":"e"},{"q":"How many chromosomes are in a normal human body (somatic) cell?","a":["46","23","12","92"],"c":0,"t":"Genetics","fb":"Body cells are diploid with 46 chromosomes.","d":"e"},{"q":"Which term means LOW sodium?","a":["Hyponatremia","Hypernatremia","Hypokalemia","Hypercalcemia"],"c":0,"t":"Fluids & Electrolytes","fb":"'Hypo' = low, 'natremia' = sodium.","d":"e"},{"q":"Down syndrome is also called trisomy ___.","a":["21","13","18","23"],"c":0,"t":"Chromosomal Disorders","fb":"Down syndrome = trisomy 21.","d":"e"},{"q":"Atrophy means cells become ___.","a":["Smaller","Larger","More numerous","A different type"],"c":0,"t":"Cellular Adaptation","fb":"Atrophy = a decrease in cell size.","d":"e"},{"q":"The most common cause of cell injury is a lack of ___.","a":["Oxygen (hypoxia)","Sodium","Protein","Water"],"c":0,"t":"Cell Injury","fb":"Hypoxia (low oxygen) is the most common cause of cell injury.","d":"e"},{"q":"Normal blood pH is about:","a":["7.4 (7.35–7.45)","7.0","8.0","6.5"],"c":0,"t":"Acid-Base","fb":"Normal arterial pH is 7.35–7.45.","d":"e"},{"q":"Apoptosis is best described as ___ cell death.","a":["Programmed (planned)","Uncontrolled","Infectious","Accidental"],"c":0,"t":"Cell Injury","fb":"Apoptosis is programmed, non-inflammatory cell death.","d":"e"},{"q":"Cystic fibrosis is inherited in which pattern?","a":["Autosomal recessive","Autosomal dominant","X-linked dominant","Mitochondrial"],"c":0,"t":"Inheritance","fb":"CF is autosomal recessive (two copies needed).","d":"e"},{"q":"Epigenetics changes gene ___ without changing the DNA sequence.","a":["Expression","Length","Number","Location"],"c":0,"t":"Epigenetics","fb":"Epigenetics alters expression, not the underlying sequence.","d":"e"},{"q":"Two parents are both carriers of cystic fibrosis (autosomal recessive). What is the chance EACH child is affected?","a":["25%","50%","75%","100%"],"c":0,"t":"Inheritance","fb":"Two carriers (Aa x Aa) → 25% affected, 50% carriers, 25% unaffected.","d":"m"},{"q":"A father has Huntington disease (autosomal dominant). What is the risk to each of his children?","a":["50%","25%","100%","0%"],"c":0,"t":"Inheritance","fb":"One affected parent with an autosomal dominant allele confers ~50% risk to each child.","d":"m"},{"q":"A boy has hemophilia A (X-linked recessive). His mother is an unaffected carrier and his father is unaffected. Who transmitted the gene?","a":["His mother (on her X chromosome)","His father","Both parents equally","Neither — it was a new mutation in the father"],"c":0,"t":"Inheritance","fb":"X-linked recessive: an affected son inherits the X (with the gene) from his carrier mother.","d":"m"},{"q":"A trait appears in every generation, affects males and females equally, and never skips. Which inheritance pattern fits best?","a":["Autosomal dominant","Autosomal recessive","X-linked recessive","Mitochondrial"],"c":0,"t":"Inheritance","fb":"No skipping, both sexes, every generation → autosomal dominant.","d":"m"},{"q":"A disorder is passed from affected mothers to ALL of their children but never from fathers. This is:","a":["Mitochondrial inheritance","Autosomal dominant","X-linked dominant","Autosomal recessive"],"c":0,"t":"Inheritance","fb":"Mitochondria are maternally inherited, so all children of an affected mother may be affected.","d":"m"},{"q":"Why does a frameshift mutation usually disrupt a protein more than a single missense mutation?","a":["It shifts the reading frame, changing every codon downstream","It changes only one amino acid","It never changes the protein","It only affects non-coding DNA"],"c":0,"t":"Genetics","fb":"Insertions/deletions shift the reading frame, garbling all downstream codons.","d":"m"},{"q":"A silent mutation does not change the protein because:","a":["The altered codon still codes for the same amino acid","It deletes the whole gene","It always occurs in an intron","It reverses transcription"],"c":0,"t":"Genetics","fb":"Silent (synonymous) mutations code for the same amino acid, so the protein is unchanged.","d":"m"},{"q":"Nondisjunction during meiosis is the direct cause of:","a":["Aneuploidy (an abnormal chromosome number)","A point mutation","Epigenetic methylation","A frameshift"],"c":0,"t":"Chromosomal Disorders","fb":"Failure of chromosomes to separate (nondisjunction) yields trisomy/monosomy = aneuploidy.","d":"m"},{"q":"A short-statured teenage girl has webbed neck, no menses, and gonadal dysgenesis. The most likely karyotype is:","a":["45,X","47,XXY","47,XX,+21","46,XX"],"c":0,"t":"Chromosomal Disorders","fb":"Turner syndrome (45,X): short stature, gonadal dysgenesis, lymphedema/webbed neck.","d":"m"},{"q":"A long-term smoker's bronchial lining changes from columnar to squamous epithelium. This adaptation is:","a":["Metaplasia","Hyperplasia","Atrophy","Necrosis"],"c":0,"t":"Cellular Adaptation","fb":"Chronic irritation drives metaplasia (one mature cell type replaced by another).","d":"m"},{"q":"Which cellular adaptation is considered potentially PRE-malignant if it persists?","a":["Dysplasia","Atrophy","Hypertrophy","Hyperplasia"],"c":0,"t":"Cellular Adaptation","fb":"Dysplasia (disordered growth) can progress toward malignancy.","d":"m"},{"q":"A bodybuilder's enlarged skeletal muscles result mainly from:","a":["Hypertrophy (bigger cells)","Hyperplasia (more cells)","Metaplasia","Dysplasia"],"c":0,"t":"Cellular Adaptation","fb":"Skeletal muscle enlarges by increasing cell SIZE (hypertrophy).","d":"m"},{"q":"After a myocardial infarction, the dead heart muscle shows pale, firm tissue. This is which type of necrosis?","a":["Coagulative necrosis","Liquefactive necrosis","Caseous necrosis","Fat necrosis"],"c":0,"t":"Cell Injury","fb":"Ischemic death of most solid organs (heart) → coagulative necrosis.","d":"m"},{"q":"Brain tissue after an ischemic stroke becomes soft and liquefied. This is:","a":["Liquefactive necrosis","Coagulative necrosis","Caseous necrosis","Fibrinoid necrosis"],"c":0,"t":"Cell Injury","fb":"The brain undergoes liquefactive necrosis after infarction.","d":"m"},{"q":"When a cell is deprived of oxygen, it first shifts to which energy pathway, producing lactic acid?","a":["Anaerobic glycolysis","Oxidative phosphorylation","Beta-oxidation","Ketogenesis"],"c":0,"t":"Cell Injury","fb":"Hypoxic cells switch to anaerobic glycolysis, generating lactic acid and lowering pH.","d":"m"},{"q":"A patient vomiting for 3 days (losing gastric acid) develops which acid–base disturbance?","a":["Metabolic alkalosis","Metabolic acidosis","Respiratory acidosis","Respiratory alkalosis"],"c":0,"t":"Acid-Base","fb":"Loss of gastric HCl raises pH → metabolic alkalosis.","d":"m"},{"q":"A COPD patient retaining CO2 will most likely show:","a":["Respiratory acidosis","Respiratory alkalosis","Metabolic alkalosis","Normal gases"],"c":0,"t":"Acid-Base","fb":"CO2 retention lowers pH → respiratory acidosis.","d":"m"},{"q":"A patient hyperventilating during a panic attack develops:","a":["Respiratory alkalosis","Respiratory acidosis","Metabolic acidosis","Metabolic alkalosis"],"c":0,"t":"Acid-Base","fb":"Blowing off CO2 raises pH → respiratory alkalosis.","d":"m"},{"q":"A marathon runner who drank large volumes of plain water becomes confused and has a seizure. The likely cause is:","a":["Hyponatremia (dilutional)","Hypernatremia","Hyperkalemia","Hypercalcemia"],"c":0,"t":"Fluids & Electrolytes","fb":"Excess free water dilutes sodium → hyponatremia with neurologic symptoms.","d":"m"},{"q":"A patient with chronic kidney disease shows peaked T waves on the monitor. The nurse suspects:","a":["Hyperkalemia","Hypokalemia","Hyponatremia","Hypocalcemia"],"c":0,"t":"Fluids & Electrolytes","fb":"Impaired potassium excretion in CKD → hyperkalemia with peaked T waves.","d":"m"}]},"2":{"title":"Week 2 — Immunity & Inflammation","slides":{"Innate vs Adaptive":"9, 11","Inflammation":"10","Antibodies":"12","Immunity Types":"13","Vaccines":"14","Hypersensitivity":"17–22","Transplant":"23, 39","Autoimmunity":"25–26, 34–35","Immune Deficiency":"27, 40–48","Alloimmunity/Transfusion":"36–38","HIV/AIDS":"49–51","Infection/Healing":"29–30"},"questions":[{"q":"Which are features of INNATE immunity? Select all that apply.","a":["Physical barriers such as skin and mucous membranes","Inflammation, fever, and the vascular response","NK cells and phagocytes","Memory that strengthens on re-exposure"],"c":0,"t":"Innate vs Adaptive","fb":"Innate immunity is fast and nonspecific (barriers, inflammation, NK cells/phagocytes). Memory is a feature of ADAPTIVE immunity.","d":"m"},{"q":"The defining features of ADAPTIVE immunity are:","a":["Specificity for a particular antigen and immunologic memory","Speed and complete lack of specificity","Physical barriers only","No involvement of lymphocytes"],"c":0,"t":"Innate vs Adaptive","fb":"Adaptive immunity is specific and remembers (faster, stronger on re-exposure).","d":"m"},{"q":"Humoral immunity is mediated by which cells and product?","a":["B cells producing antibodies","CD8 cytotoxic T cells","NK cells","Neutrophils"],"c":0,"t":"Innate vs Adaptive","fb":"Humoral = B cells/plasma cells making antibodies, targeting extracellular pathogens and toxins.","d":"m"},{"q":"Match the T-cell roles. Which statements are correct? Select all that apply.","a":["CD4 helper T cells orchestrate the immune response","CD8 cytotoxic T cells kill infected or cancerous cells","Regulatory T cells dampen the response and maintain tolerance","B cells are the cytotoxic killers of infected cells"],"c":0,"t":"Innate vs Adaptive","fb":"CD4 help, CD8 kill, Tregs regulate. B cells make antibodies (they are not the cytotoxic killers).","d":"m"},{"q":"Place the inflammation cascade in order.","a":["Tissue injury → vascular response → cellular response","Vascular response → tissue injury → cellular response","Cellular response → vascular response → tissue injury","Tissue injury → cellular response → vascular response"],"c":0,"t":"Inflammation","fb":"Injury (mast cells/histamine, complement, cytokines) → vasodilation/permeability → cellular influx.","d":"m"},{"q":"During the vascular phase of inflammation, vasodilation and increased permeability produce:","a":["Redness, heat, and swelling","Pallor and coolness","Immediate scar formation","Decreased blood flow to the area"],"c":0,"t":"Inflammation","fb":"Vasodilation + leaky capillaries → the classic redness, heat, and swelling of inflammation.","d":"m"},{"q":"Which cell is the FIRST cellular responder to acute inflammation, followed by macrophages?","a":["Neutrophil","Eosinophil","Plasma cell","NK cell"],"c":0,"t":"Inflammation","fb":"Neutrophils arrive first; macrophages follow to phagocytose pathogens and debris.","d":"m"},{"q":"Mast cells contribute to early inflammation primarily by releasing:","a":["Histamine","Insulin","Antibodies","Reverse transcriptase"],"c":0,"t":"Inflammation","fb":"Mast cell histamine drives early vasodilation and increased permeability.","d":"m"},{"q":"Which antibody is MOST abundant in serum and crosses the placenta?","a":["IgG","IgM","IgA","IgE"],"c":0,"t":"Antibodies","fb":"IgG is most abundant, provides long-term immunity, opsonizes, and crosses the placenta for neonatal protection.","d":"m"},{"q":"Which antibody is the EARLIEST produced and a strong agglutinator (first responder)?","a":["IgM","IgG","IgA","IgD"],"c":0,"t":"Antibodies","fb":"IgM appears first in blood and agglutinates strongly.","d":"m"},{"q":"Which antibody dominates MUCOSAL defense and breast milk?","a":["IgA","IgG","IgE","IgM"],"c":0,"t":"Antibodies","fb":"IgA protects mucosal surfaces and provides passive immunity through breast milk.","d":"m"},{"q":"Which antibody binds mast cells/basophils and mediates allergy and parasite defense?","a":["IgE","IgG","IgA","IgD"],"c":0,"t":"Antibodies","fb":"IgE drives Type I allergic reactions and helps defend against parasites.","d":"m"},{"q":"A breastfed newborn of a vaccinated mother is protected in the first months by:","a":["Natural passive immunity (maternal IgG across placenta, IgA in breast milk)","Natural active immunity from in utero infection","Artificial active immunity from a birth vaccine","Innate immunity alone"],"c":0,"t":"Immunity Types","fb":"Maternal antibodies = natural PASSIVE immunity (received, not self-made).","d":"m"},{"q":"Recovering from a chickenpox infection and becoming immune is an example of:","a":["Natural active immunity","Natural passive immunity","Artificial active immunity","Artificial passive immunity"],"c":0,"t":"Immunity Types","fb":"Active = your own response; natural = from infection (not a vaccine).","d":"m"},{"q":"Receiving a rabies immunoglobulin injection provides:","a":["Artificial passive immunity","Artificial active immunity","Natural active immunity","Lifelong active immunity"],"c":0,"t":"Immunity Types","fb":"Pre-made antibodies given by injection = artificial PASSIVE immunity (immediate but temporary).","d":"m"},{"q":"Which vaccines are LIVE-ATTENUATED? Select all that apply.","a":["MMR","Varicella","Rotavirus","Tetanus toxoid"],"c":0,"t":"Vaccines","fb":"MMR, varicella, and rotavirus are live-attenuated. Tetanus is a toxoid vaccine.","d":"m"},{"q":"A toxoid vaccine works by:","a":["Using an inactivated toxin to generate immunity","Using a weakened live pathogen","Delivering mRNA instructions to the cell","Injecting pre-formed antibodies"],"c":0,"t":"Vaccines","fb":"Toxoid vaccines (tetanus, diphtheria) use inactivated toxins.","d":"m"},{"q":"mRNA / viral-vector vaccines generate immunity by:","a":["Instructing the patient's own cells to make the target antigen","Injecting the killed whole pathogen","Providing maternal antibodies","Using an inactivated toxin"],"c":0,"t":"Vaccines","fb":"mRNA/viral-vector vaccines deliver instructions so the cell makes the antigen (e.g., COVID-19 mRNA).","d":"m"},{"q":"Which hypersensitivity type is IgE-mediated and immediate (anaphylaxis, asthma)?","a":["Type I","Type II","Type III","Type IV"],"c":0,"t":"Hypersensitivity","fb":"Type I: allergen → IgE → mast-cell histamine release within minutes (the 'A' in ACID = Allergic).","d":"m"},{"q":"A nursing student develops firm, red induration 48 hours after a TB skin test. This is which type?","a":["Type IV — delayed, T-cell mediated","Type I — IgE mediated","Type II — cytotoxic","Type III — immune complex"],"c":0,"t":"Hypersensitivity","fb":"Delayed (24–72 h), antibody-free, T-cell mediated = Type IV (PPD, contact dermatitis).","d":"m"},{"q":"Type II (cytotoxic) hypersensitivity is mediated by:","a":["IgG/IgM antibodies binding cell-surface antigens, often with complement","IgE on mast cells","Immune-complex deposition","T cells releasing cytokines with no antibody"],"c":0,"t":"Hypersensitivity","fb":"Type II: antibody binds a cell-surface antigen → destruction (e.g., HDN, Graves, myasthenia gravis).","d":"m"},{"q":"Type III hypersensitivity is BEST described as:","a":["Immune-complex deposition in tissues causing inflammation","IgE-mediated mast-cell degranulation","Delayed T-cell reaction without antibody","Pre-formed antibody causing hyperacute rejection"],"c":0,"t":"Hypersensitivity","fb":"Type III: antigen–antibody complexes deposit in tissue (SLE, serum sickness, post-strep GN).","d":"m"},{"q":"Using the ACID mnemonic, match the letters to the types. Which pairings are correct? Select all that apply.","a":["A = Type I, Allergic (IgE)","C = Type II, Cytotoxic","I = Type III, Immune complex","D = Type IV, Delayed"],"c":0,"t":"Hypersensitivity","fb":"ACID: Allergic (I), Cytotoxic (II), Immune-complex (III), Delayed (IV).","d":"m"},{"q":"Which conditions are classic Type IV (delayed) reactions? Select all that apply.","a":["Poison ivy / contact dermatitis","PPD (TB) skin test","Chronic transplant rejection","Anaphylaxis to peanuts"],"c":0,"t":"Hypersensitivity","fb":"Type IV: poison ivy, PPD, chronic rejection, GVHD. Anaphylaxis is Type I.","d":"m"},{"q":"Hyperacute transplant rejection (minutes to hours) is caused by:","a":["Pre-existing recipient antibodies against graft antigens (Type II)","A delayed T-cell response (Type IV)","Immune-complex deposition","An IgE/mast-cell reaction"],"c":0,"t":"Transplant","fb":"Hyperacute rejection = pre-formed antibodies attack the graft immediately (a Type II mechanism).","d":"m"},{"q":"Acute transplant rejection (days to months) is primarily:","a":["A cell-mediated (T-cell) immune response","Pre-formed antibody mediated","An IgE allergic response","Caused by complement deficiency"],"c":0,"t":"Transplant","fb":"Acute rejection is mainly cell-mediated (Type IV-type mechanism), occurring over days to months.","d":"m"},{"q":"What is the major target in transplant rejection?","a":["MHC molecules (HLAs)","ABO antigens only","IgE receptors","Complement C3"],"c":0,"t":"Transplant","fb":"HLA/MHC mismatch is the principal driver of graft rejection.","d":"m"},{"q":"Autoimmunity is fundamentally a:","a":["Breakdown in immunologic tolerance of self-antigens","Reaction to another individual's tissues","Failure of the immune system to respond at all","Normal response to environmental allergens"],"c":0,"t":"Autoimmunity","fb":"Autoimmunity = loss of self-tolerance; the body attacks its own antigens.","d":"m"},{"q":"Which autoimmune disease targets the TSH receptor and causes hyperthyroidism with exophthalmos?","a":["Graves disease","Hashimoto thyroiditis","Type 1 diabetes","Multiple sclerosis"],"c":0,"t":"Autoimmunity","fb":"Graves: antibodies stimulate the TSH receptor → hyperthyroidism and exophthalmos.","d":"m"},{"q":"Hashimoto thyroiditis is characterized by:","a":["Hypothyroidism with anti-TPO antibodies","Hyperthyroidism with TSH-receptor antibodies","Destruction of pancreatic beta cells","CNS myelin destruction"],"c":0,"t":"Autoimmunity","fb":"Hashimoto: autoimmune destruction of thyroid tissue → hypothyroidism; anti-TPO antibodies.","d":"m"},{"q":"Which features fit systemic lupus erythematosus (SLE)? Select all that apply.","a":["Positive ANA","Malar (butterfly) rash","Lupus nephritis","Anti-TSH receptor antibodies causing hyperthyroidism"],"c":0,"t":"Autoimmunity","fb":"SLE: +ANA, malar rash, nephritis, multisystem inflammation. Anti-TSH-receptor antibodies belong to Graves.","d":"m"},{"q":"Multiple sclerosis is an autoimmune attack on:","a":["CNS myelin","Synovial joints","Pancreatic beta cells","The TSH receptor"],"c":0,"t":"Autoimmunity","fb":"MS = immune-mediated demyelination of CNS myelin → relapsing neurologic deficits.","d":"m"},{"q":"Type 1 diabetes mellitus results from autoimmune destruction of:","a":["Pancreatic beta cells (insulin deficiency)","Thyroid follicular cells","Synovial joints","CNS myelin"],"c":0,"t":"Autoimmunity","fb":"T1DM: autoimmune loss of insulin-producing beta cells.","d":"m"},{"q":"Distinguish the terms. Which definitions are correct? Select all that apply.","a":["Allergy = hypersensitivity to environmental (exogenous) antigens","Autoimmunity = loss of tolerance to self-antigens","Alloimmunity = reaction to another individual's tissues","Immune deficiency = an overactive immune response"],"c":0,"t":"Immune Deficiency","fb":"Immune deficiency is an INSUFFICIENT response, not an overactive one. The other three are correct.","d":"m"},{"q":"Primary immune deficiencies are usually:","a":["Congenital, often from a single gene defect, appearing early in life","Acquired from another illness or treatment","Always fatal in infancy","Caused by chemotherapy"],"c":0,"t":"Immune Deficiency","fb":"Primary = congenital/genetic (SCID, DiGeorge, Bruton, Wiskott-Aldrich); secondary = acquired.","d":"m"},{"q":"DiGeorge syndrome results from underdevelopment of the thymus and parathyroids, leading to:","a":["T-cell deficiency and hypocalcemia","B-cell-only deficiency","Excess antibody production","Complement overactivation"],"c":0,"t":"Immune Deficiency","fb":"DiGeorge: absent/partial thymus → T-cell deficiency; absent parathyroids → calcium deficiency.","d":"m"},{"q":"Which is the MOST COMMON category of primary immune deficiency?","a":["Predominantly antibody (B-cell) deficiencies","Complement deficiencies","Combined T- and B-cell deficiencies","Phagocyte deficiencies"],"c":0,"t":"Immune Deficiency","fb":"Antibody deficiencies (e.g., Bruton agammaglobulinemia) are the most common primary immunodeficiencies.","d":"m"},{"q":"The MOST COMMON overall cause of immune deficiency is:","a":["Secondary (acquired) causes such as illness, immunosuppressants, or AIDS","Single-gene congenital defects","Complement C3 deficiency","Mannose-binding lectin deficiency"],"c":0,"t":"Immune Deficiency","fb":"Secondary (acquired) deficiencies are far more common than primary ones.","d":"m"},{"q":"T-cell defects classically increase susceptibility to which organisms?","a":["Viral, fungal, and atypical organisms","Only encapsulated bacteria","Only parasites","No increased susceptibility"],"c":0,"t":"Immune Deficiency","fb":"T-cell defects → viral/fungal/atypical infections; B-cell/phagocyte defects → encapsulated bacteria.","d":"m"},{"q":"Alloimmunity includes which clinical settings? Select all that apply.","a":["Transfusion reactions","Transplant rejection","Reaction to fetal antigens in pregnancy","Poison ivy contact dermatitis"],"c":0,"t":"Alloimmunity/Transfusion","fb":"Alloimmunity = reaction to another person's tissues (transfusion, transplant, pregnancy). Poison ivy is Type IV against an environmental antigen.","d":"m"},{"q":"A person with type O blood has which plasma antibodies and donor status?","a":["Anti-A and anti-B antibodies; universal donor","No antibodies; universal recipient","Anti-A only; universal recipient","Anti-B only; universal donor"],"c":0,"t":"Alloimmunity/Transfusion","fb":"Type O RBCs have no A/B antigens (universal donor) but the plasma has anti-A and anti-B.","d":"m"},{"q":"A person with type AB blood is the:","a":["Universal recipient (no anti-A or anti-B antibodies)","Universal donor","Carrier of anti-A and anti-B","Rh-negative by definition"],"c":0,"t":"Alloimmunity/Transfusion","fb":"AB cells carry both antigens and the plasma has neither antibody → universal recipient.","d":"m"},{"q":"Hemolytic disease of the newborn occurs when:","a":["An Rh-negative mother forms anti-Rh antibodies against an Rh-positive fetus","An Rh-positive mother carries an Rh-negative fetus","The fetus and mother share identical HLA","Maternal IgA crosses the placenta"],"c":0,"t":"Alloimmunity/Transfusion","fb":"Rh-negative mother sensitized to Rh-positive fetal cells makes anti-Rh IgG that endangers later pregnancies.","d":"m"},{"q":"How is hemolytic disease of the newborn prevented?","a":["Rh immunoglobulin (RhoGAM) at ~28 weeks and after delivery","Giving the mother type O blood","Vaccinating the newborn at birth","IV antibiotics during labor"],"c":0,"t":"Alloimmunity/Transfusion","fb":"RhoGAM prevents maternal sensitization to Rh-positive fetal red cells.","d":"m"},{"q":"HIV is a retrovirus that primarily targets which cell via gp120?","a":["CD4+ helper T lymphocytes","CD8 cytotoxic T cells","Neutrophils","Plasma cells"],"c":0,"t":"HIV/AIDS","fb":"HIV gp120 binds CD4 on helper T cells; their depletion causes immunodeficiency.","d":"m"},{"q":"Which enzymes does HIV carry to replicate? Select all that apply.","a":["Reverse transcriptase","Integrase","Protease","DNA helicase only"],"c":0,"t":"HIV/AIDS","fb":"HIV carries reverse transcriptase, integrase, and protease — each a drug target in ART.","d":"m"},{"q":"By definition, AIDS is diagnosed when the CD4+ count falls below:","a":["200/mm³","500/mm³","1000/mm³","50/mm³"],"c":0,"t":"HIV/AIDS","fb":"A CD4+ count < 200/mm³ (or an AIDS-defining illness) defines AIDS.","d":"m"},{"q":"Which statement about antiretroviral therapy (ART) is correct?","a":["It uses combination drugs and greatly reduces mortality but is not curative","It cures HIV in most patients","It is a single-drug regimen","It is contraindicated in pregnancy"],"c":0,"t":"HIV/AIDS","fb":"ART combines drug classes to suppress HIV; it lowers mortality and transmission but does not cure infection.","d":"m"},{"q":"Place the stages of infection in the correct order.","a":["Exposure → incubation → prodromal → illness → recovery","Incubation → exposure → illness → prodromal → recovery","Prodromal → exposure → incubation → illness → recovery","Exposure → illness → incubation → prodromal → recovery"],"c":0,"t":"Infection/Healing","fb":"Exposure, then silent incubation, mild prodrome, full illness, then recovery.","d":"m"},{"q":"Place the phases of wound healing in order.","a":["Hemostasis → inflammation → proliferation → remodeling","Inflammation → hemostasis → remodeling → proliferation","Proliferation → inflammation → hemostasis → remodeling","Remodeling → proliferation → inflammation → hemostasis"],"c":0,"t":"Infection/Healing","fb":"Bleeding stops (hemostasis), debris cleared (inflammation), tissue rebuilt (proliferation), scar matures (remodeling).","d":"m"},{"q":"B cells primarily produce ___.","a":["Antibodies","Insulin","Histamine","Myelin"],"c":0,"t":"Innate vs Adaptive","fb":"B cells/plasma cells make antibodies.","d":"e"},{"q":"Which antibody crosses the placenta to protect the newborn?","a":["IgG","IgE","IgM","IgD"],"c":0,"t":"Antibodies","fb":"IgG crosses the placenta.","d":"e"},{"q":"Anaphylaxis is which type of hypersensitivity?","a":["Type I","Type II","Type III","Type IV"],"c":0,"t":"Hypersensitivity","fb":"Anaphylaxis is an immediate, IgE-mediated Type I reaction.","d":"e"},{"q":"Getting a vaccine gives you which kind of immunity?","a":["Artificial active","Natural passive","Innate","Artificial passive"],"c":0,"t":"Immunity Types","fb":"Vaccines trigger your own response = artificial ACTIVE immunity.","d":"e"},{"q":"The first immune cell to arrive at acute inflammation is the ___.","a":["Neutrophil","Plasma cell","B cell","NK cell"],"c":0,"t":"Inflammation","fb":"Neutrophils arrive first, then macrophages.","d":"e"},{"q":"HIV mainly attacks which immune cells?","a":["CD4 helper T cells","Red blood cells","Neutrophils","Platelets"],"c":0,"t":"HIV/AIDS","fb":"HIV targets CD4+ helper T cells.","d":"e"},{"q":"Autoimmunity means the immune system attacks ___.","a":["The body's own cells (self)","Only viruses","Only bacteria","Transplanted organs only"],"c":0,"t":"Autoimmunity","fb":"Autoimmunity = loss of tolerance to self.","d":"e"},{"q":"Blood type O is the universal ___.","a":["Donor","Recipient","Antigen","Plasma"],"c":0,"t":"Alloimmunity/Transfusion","fb":"Type O has no A/B antigens → universal donor.","d":"e"},{"q":"A live attenuated vaccine uses a ___ form of the pathogen.","a":["Weakened","Killed","Toxin","Synthetic only"],"c":0,"t":"Vaccines","fb":"Live attenuated = weakened live pathogen (e.g., MMR).","d":"e"},{"q":"Redness, heat, and swelling are classic signs of ___.","a":["Inflammation","Cancer","Anemia","Dehydration"],"c":0,"t":"Inflammation","fb":"These are cardinal signs of the inflammatory response.","d":"e"},{"q":"Minutes after a bee sting, a patient develops hives, wheezing, and throat tightness. This is which hypersensitivity type?","a":["Type I (IgE-mediated)","Type II (cytotoxic)","Type III (immune complex)","Type IV (delayed)"],"c":0,"t":"Hypersensitivity","fb":"Immediate IgE/mast-cell reaction = Type I (anaphylaxis).","d":"m"},{"q":"A patient receives ABO-incompatible blood and has antibody-mediated red-cell destruction. This is:","a":["Type II (cytotoxic) hypersensitivity","Type I","Type III","Type IV"],"c":0,"t":"Hypersensitivity","fb":"Antibodies against cell-surface (RBC) antigens cause Type II destruction.","d":"m"},{"q":"In SLE, antigen–antibody complexes deposit in the kidney and cause inflammation. This mechanism is:","a":["Type III (immune complex)","Type I","Type II","Type IV"],"c":0,"t":"Hypersensitivity","fb":"Immune-complex deposition = Type III (e.g., lupus nephritis).","d":"m"},{"q":"A gardener develops an itchy rash 2 days after touching poison ivy. This delayed reaction is:","a":["Type IV (T-cell mediated)","Type I","Type II","Type III"],"c":0,"t":"Hypersensitivity","fb":"Delayed (24–72 h), T-cell mediated contact dermatitis = Type IV.","d":"m"},{"q":"On re-exposure to a known antigen, the rapid 'memory' antibody response is dominated by:","a":["IgG","IgM","IgE","IgD"],"c":0,"t":"Antibodies","fb":"Secondary/memory responses are dominated by IgG (faster, stronger).","d":"m"},{"q":"Which antibody class rises FIRST during an initial (primary) infection?","a":["IgM","IgG","IgA","IgE"],"c":0,"t":"Antibodies","fb":"IgM is the first antibody produced in a primary response.","d":"m"},{"q":"A patient receives tetanus immune globulin (pre-made antibodies) after a wound. This provides:","a":["Artificial passive immunity","Artificial active immunity","Natural active immunity","Natural passive immunity"],"c":0,"t":"Immunity Types","fb":"Injected antibodies = artificial PASSIVE immunity (immediate, temporary).","d":"m"},{"q":"Recovering from a natural measles infection produces which type of immunity?","a":["Natural active","Natural passive","Artificial active","Artificial passive"],"c":0,"t":"Immunity Types","fb":"Your own response to natural infection = natural ACTIVE immunity.","d":"m"},{"q":"Why are LIVE attenuated vaccines generally avoided in severely immunocompromised patients?","a":["The weakened organism could still cause infection","They contain no antigen","They are always ineffective","They only work in children"],"c":0,"t":"Vaccines","fb":"A weakened live pathogen can cause disease if the immune system can't control it.","d":"m"},{"q":"Which cell predominates in CHRONIC inflammation (vs the neutrophil of acute inflammation)?","a":["Macrophage","Platelet","Plasma cell only","Erythrocyte"],"c":0,"t":"Inflammation","fb":"Macrophages dominate chronic inflammation; neutrophils dominate the acute phase.","d":"m"},{"q":"CD8 cytotoxic T cells are most important for killing:","a":["Virus-infected and tumor cells","Extracellular bacteria via antibodies","Allergens","Healthy self-cells"],"c":0,"t":"Innate vs Adaptive","fb":"CD8 T cells destroy intracellular threats (viral/tumor cells).","d":"m"},{"q":"A young woman has a malar 'butterfly' rash, joint pain, fatigue, and a positive ANA. Most likely diagnosis:","a":["Systemic lupus erythematosus","Graves disease","Multiple sclerosis","Type 1 diabetes"],"c":0,"t":"Autoimmunity","fb":"Malar rash + arthralgia + positive ANA strongly suggests SLE.","d":"m"},{"q":"A patient has weight loss, heat intolerance, palpitations, and bulging eyes. The autoimmune cause is:","a":["Graves disease","Hashimoto thyroiditis","Addison disease","Type 1 diabetes"],"c":0,"t":"Autoimmunity","fb":"Hyperthyroid signs plus exophthalmos = Graves disease.","d":"m"},{"q":"Recurrent infections with ENCAPSULATED bacteria most suggest a defect in:","a":["Antibody (B-cell) or complement function","Cytotoxic T cells only","Mast cells","Red blood cells"],"c":0,"t":"Immune Deficiency","fb":"Antibody/complement defects predispose to encapsulated bacterial infections.","d":"m"},{"q":"Recurrent VIRAL and FUNGAL infections most suggest a defect in:","a":["T-cell function","Antibody production only","Complement only","Platelets"],"c":0,"t":"Immune Deficiency","fb":"T-cell defects increase viral, fungal, and atypical infections.","d":"m"},{"q":"An Rh-negative mother is pregnant with her second Rh-positive baby. The main risk is:","a":["Hemolytic disease of the newborn from maternal anti-Rh antibodies","Maternal anemia only","No risk in any pregnancy","Diabetes in the newborn"],"c":0,"t":"Alloimmunity/Transfusion","fb":"Prior sensitization makes anti-Rh IgG that attacks the Rh-positive fetus; prevent with RhoGAM.","d":"m"},{"q":"A transplanted kidney fails within minutes due to pre-existing recipient antibodies. This is:","a":["Hyperacute rejection","Acute rejection","Chronic rejection","Graft-versus-host disease"],"c":0,"t":"Transplant","fb":"Pre-formed antibodies cause immediate (hyperacute) rejection.","d":"m"},{"q":"An HIV patient's CD4 count drops below 200/mm3. This means the patient now meets criteria for:","a":["AIDS","Cure","Latent HIV only","Seroconversion"],"c":0,"t":"HIV/AIDS","fb":"CD4 < 200/mm3 (or an AIDS-defining illness) defines AIDS.","d":"m"},{"q":"Which are common triggers of anaphylaxis? Select all that apply.","a":["Peanuts","Bee stings","Shellfish","Sunlight"],"c":0,"t":"Hypersensitivity","fb":"Foods (peanuts, shellfish) and insect stings are classic anaphylaxis triggers; sunlight is not.","d":"m"},{"q":"A patient with HIV is started on combination antiretroviral therapy (ART). The nurse explains that ART:","a":["Suppresses the virus and lowers mortality but is not a cure","Cures HIV in a few weeks","Is a single pill that eradicates the virus","Should be stopped once CD4 normalizes"],"c":0,"t":"HIV/AIDS","fb":"ART combines drug classes to control HIV; it reduces mortality/transmission but does not cure.","d":"m"}]},"3":{"title":"Week 3 — Oncology (Biology of Cancer)","slides":{"Benign vs Malignant":"8","Tumor Nomenclature":"9","Carcinogenesis Stages":"10","Hallmarks of Cancer":"11","Oncogenes":"12","Tumor Suppressors":"13–14","Angiogenesis/Metastasis":"15","Epidemiology":"20","Risk Factors":"21–22","Carcinogens":"23","Oncogenic Viruses":"24","Pediatric Cancer":"25","Local Effects":"30","Systemic Effects":"31","Paraneoplastic":"32","Oncologic Emergencies":"33–34"},"questions":[{"q":"Which features describe a MALIGNANT (vs benign) tumor? Select all that apply.","a":["Poorly differentiated with anaplasia and pleomorphism","Invades and crosses tissue planes and vessels","Can metastasize via blood, lymph, or seeding","Encapsulated with clear margins"],"c":0,"t":"Benign vs Malignant","fb":"Malignant = poorly differentiated, invasive, metastatic. Encapsulation with clear margins is a BENIGN feature.","d":"m"},{"q":"Which characteristic of tumor cells DIRECTLY allows spread to distant organs?","a":["Tumor cells invade tissue and enter vessels","Tumor cells remain mature and well organized","Tumor cells stay inside a fibrous capsule","Tumor cells divide only during repair"],"c":0,"t":"Benign vs Malignant","fb":"Invasion into vessels (blood/lymph) is the step that enables metastasis.","d":"m"},{"q":"A benign tumor of glandular epithelium is called a(n):","a":["Adenoma","Adenocarcinoma","Sarcoma","Carcinoma"],"c":0,"t":"Tumor Nomenclature","fb":"'-oma' on epithelium = benign (adenoma); malignant epithelial tumors are carcinomas/adenocarcinomas.","d":"m"},{"q":"A malignant tumor arising from connective/mesenchymal tissue (e.g., bone) is a:","a":["Sarcoma (e.g., osteosarcoma)","Carcinoma","Adenoma","Lymphoma"],"c":0,"t":"Tumor Nomenclature","fb":"Mesenchymal malignancies are sarcomas (osteosarcoma, liposarcoma, fibrosarcoma).","d":"m"},{"q":"Which '-oma' names are actually MALIGNANT despite the suffix? Select all that apply.","a":["Leukemia","Lymphoma","Melanoma","Lipoma"],"c":0,"t":"Tumor Nomenclature","fb":"Exceptions to the '-oma = benign' rule: leukemia, lymphoma, melanoma, mesothelioma. Lipoma is benign.","d":"m"},{"q":"Malignancies of epithelial origin are termed:","a":["Carcinomas","Sarcomas","Gliomas","Teratomas"],"c":0,"t":"Tumor Nomenclature","fb":"Epithelial malignancies = carcinomas (e.g., squamous cell carcinoma, adenocarcinoma).","d":"m"},{"q":"Place the stages of cancer development in order.","a":["Initiation → promotion → progression → invasion/metastasis","Promotion → initiation → invasion → progression","Progression → promotion → initiation → metastasis","Initiation → progression → promotion → invasion"],"c":0,"t":"Carcinogenesis Stages","fb":"Initiation (first mutation) → promotion (driver accumulation) → progression (clinical tumor) → invasion/metastasis.","d":"m"},{"q":"Which statement correctly distinguishes driver from passenger mutations?","a":["Driver mutations promote cancer growth; passenger mutations accumulate but don't change behavior","Passenger mutations cause cancer; drivers are harmless","Both are required in equal numbers","Driver mutations are always inherited"],"c":0,"t":"Carcinogenesis Stages","fb":"Drivers actively push transformation; passengers are bystander mutations.","d":"m"},{"q":"Which are recognized HALLMARKS OF CANCER (Hanahan & Weinberg)? Select all that apply.","a":["Sustained proliferative signaling","Evading growth suppressors","Inducing angiogenesis","Enhanced response to apoptotic signals"],"c":0,"t":"Hallmarks of Cancer","fb":"Cancers RESIST cell death (apoptosis), they don't enhance it. The other three are true hallmarks.","d":"m"},{"q":"'Replicative immortality' in cancer cells is achieved mainly by:","a":["Reactivation of telomerase","Loss of mitochondria","Increased apoptosis","Halting the cell cycle"],"c":0,"t":"Hallmarks of Cancer","fb":"Telomerase reactivation lets cancer cells bypass the normal limit on cell divisions.","d":"m"},{"q":"The 'Warburg effect' refers to cancer cells:","a":["Reprogramming metabolism toward glycolysis even with oxygen present","Stopping all energy production","Relying solely on oxidative phosphorylation","Refusing to take up glucose"],"c":0,"t":"Hallmarks of Cancer","fb":"Cancer cells favor glycolysis (Warburg effect) — a hallmark of reprogrammed metabolism.","d":"m"},{"q":"Tumors evade immune destruction partly by exploiting checkpoints such as:","a":["PD-L1 and CTLA-4","Telomerase and VEGF","KRAS and MYC","TNF-alpha and IL-6"],"c":0,"t":"Hallmarks of Cancer","fb":"PD-L1/CTLA-4 checkpoints are hijacked to evade immune attack — the basis of checkpoint-inhibitor therapy.","d":"m"},{"q":"Proto-oncogenes normally:","a":["Regulate growth, division, and differentiation when needed","Permanently suppress all cell division","Repair every DNA break","Encode antibodies"],"c":0,"t":"Oncogenes","fb":"Proto-oncogenes are normal growth-promoting genes; a gain-of-function mutation converts them to oncogenes.","d":"m"},{"q":"Which findings are consistent with ONCOGENE activation? Select all that apply.","a":["Growth signals remain switched on","Growth-receptor expression increases","Cells produce their own growth signals","Cell-cycle drivers remain active"],"c":0,"t":"Oncogenes","fb":"Oncogene activation keeps proliferation signaling 'on' (autocrine signals, receptor overexpression, active cyclins). Loss of tumor-suppressor function is a separate mechanism.","d":"m"},{"q":"The Philadelphia chromosome in CML is a ___ that forms ___.","a":["Chromosomal translocation; BCR-ABL fusion gene","Point mutation; TP53-RB","Gene deletion; RAS-MYC","Epigenetic silencing; APC-KRAS"],"c":0,"t":"Oncogenes","fb":"t(9;22) translocation creates the BCR-ABL fusion oncogene (target of imatinib).","d":"m"},{"q":"Match oncogene activation mechanisms. Which are correct? Select all that apply.","a":["Point mutation (KRAS)","Gene amplification (HER2, MYC)","Chromosomal translocation (BCR-ABL)","Loss of both alleles (the only mechanism)"],"c":0,"t":"Oncogenes","fb":"Oncogenes activate by point mutation, amplification, translocation, or receptor overexpression — each needs only ONE hit.","d":"m"},{"q":"How many 'hits' (mutated alleles) does a tumor-suppressor gene typically require to lose function (Knudson)?","a":["Two (both alleles)","One","Three","None — they are dominant"],"c":0,"t":"Tumor Suppressors","fb":"Knudson's two-hit hypothesis: both alleles of a tumor suppressor must be lost (recessive at the cell level).","d":"m"},{"q":"TP53 is best described as:","a":["The 'guardian of the genome,' mutated in over half of human cancers","An oncogene activated by amplification","A caretaker gene that only repairs DNA","A growth factor receptor"],"c":0,"t":"Tumor Suppressors","fb":"TP53 arrests the cycle and triggers apoptosis on DNA damage; it's mutated in >50% of cancers.","d":"m"},{"q":"Inherited BRCA1/BRCA2 mutations most strongly increase risk of:","a":["Breast and ovarian cancer","Gastric cancer only","Leukemia only","Skin cancer only"],"c":0,"t":"Tumor Suppressors","fb":"BRCA1/2 are tumor suppressors; inherited mutations greatly raise breast/ovarian cancer risk.","d":"m"},{"q":"Caretaker (DNA-repair) genes such as MLH1/MSH2 in Lynch syndrome, when lost, cause:","a":["Faster accumulation of mutations due to failed DNA repair","Immediate apoptosis of all cells","Direct growth signaling","Increased telomere shortening"],"c":0,"t":"Tumor Suppressors","fb":"Caretaker gene loss destabilizes the genome so mutations pile up (Lynch syndrome / HNPCC).","d":"m"},{"q":"Why must a solid tumor induce angiogenesis once it reaches ~1–2 mm?","a":["It outgrows the distance oxygen/nutrients can diffuse","It needs to stop dividing","It must shrink to survive","Diffusion alone can supply any tumor size"],"c":0,"t":"Angiogenesis/Metastasis","fb":"Beyond ~1–2 mm, diffusion is insufficient, so the tumor releases VEGF to recruit new vessels.","d":"m"},{"q":"Which factor is the key driver of tumor angiogenesis?","a":["VEGF","Insulin","Albumin","Surfactant"],"c":0,"t":"Angiogenesis/Metastasis","fb":"VEGF (vascular endothelial growth factor) recruits new blood vessels to feed the tumor.","d":"m"},{"q":"Tumor cells breach the basement membrane and ECM largely using:","a":["Matrix metalloproteinases (MMPs)","Telomerase","Reverse transcriptase","Surfactant proteins"],"c":0,"t":"Angiogenesis/Metastasis","fb":"MMPs degrade the basement membrane/ECM, enabling local invasion.","d":"m"},{"q":"The 'seed and soil' pattern explains why metastases favor which common sites? Select all that apply.","a":["Lungs","Liver","Bone","Brain"],"c":0,"t":"Angiogenesis/Metastasis","fb":"High blood flow + permissive microenvironment make lungs, liver, bone, and brain common metastatic targets.","d":"m"},{"q":"In the United States, cancer is the ___ leading cause of death in adults.","a":["Second (after heart disease)","First","Fourth","Tenth"],"c":0,"t":"Epidemiology","fb":"Cancer is the 2nd leading cause of adult death, surpassed only by heart disease.","d":"m"},{"q":"Which cancer is the MOST LETHAL (highest mortality) in U.S. adults?","a":["Lung","Breast","Prostate","Thyroid"],"c":0,"t":"Epidemiology","fb":"Lung cancer causes the most cancer deaths (lung > colorectal > pancreatic > breast/prostate).","d":"m"},{"q":"The single largest PREVENTABLE cause of cancer is:","a":["Tobacco use","Alcohol","UV radiation","Obesity"],"c":0,"t":"Risk Factors","fb":"Tobacco is the leading preventable cause (lung, oral, esophagus, bladder, pancreas).","d":"m"},{"q":"Which are MODIFIABLE cancer risk factors? Select all that apply.","a":["Tobacco","Obesity","Physical inactivity","Age"],"c":0,"t":"Risk Factors","fb":"Tobacco, obesity, and inactivity are modifiable. Age is a non-modifiable risk factor.","d":"m"},{"q":"A patient with central obesity, high fasting glucose, and high fasting insulin has increased cancer risk because:","a":["Chronic inflammation increases and insulin signaling becomes more mitogenic","Immune surveillance increases","Oxidative stress decreases","Adipose signaling becomes less active"],"c":0,"t":"Risk Factors","fb":"Adipose-driven inflammation plus hyperinsulinemia (↑IGF-1) promote mitogenic, pro-cancer signaling.","d":"m"},{"q":"Which are NON-modifiable cancer risk factors? Select all that apply.","a":["Age","Sex","Inherited syndromes (BRCA, Lynch, Li-Fraumeni)","Tobacco use"],"c":0,"t":"Risk Factors","fb":"Age, sex, and inherited syndromes can't be changed; tobacco use is modifiable.","d":"m"},{"q":"Asbestos exposure is a CHEMICAL carcinogen classically linked to:","a":["Mesothelioma","Melanoma","Cervical cancer","Thyroid cancer"],"c":0,"t":"Carcinogens","fb":"Asbestos (a chemical carcinogen) is linked to mesothelioma and lung cancer.","d":"m"},{"q":"A 24-year-old with abnormal vaginal bleeding whose mother took DES while pregnant illustrates:","a":["Exposure to a carcinogen during fetal development (transplacental)","Exposure to oncogenic viruses in adulthood","Dietary carcinogens in adulthood","Radiation exposure in infancy"],"c":0,"t":"Carcinogens","fb":"In-utero DES exposure → clear cell adenocarcinoma of the vagina/cervix (a transplacental carcinogen).","d":"m"},{"q":"Ionizing radiation (X-rays, radon) is a PHYSICAL carcinogen most linked to:","a":["Leukemia and thyroid cancer (especially in children)","Mesothelioma","Gastric MALT lymphoma","Hepatocellular carcinoma"],"c":0,"t":"Carcinogens","fb":"Physical carcinogens (UV, ionizing radiation) → skin cancers, leukemia, and thyroid cancer.","d":"m"},{"q":"High-risk HPV (types 16, 18) drives cancer by:","a":["E6/E7 proteins inactivating p53 and Rb","Integrating reverse transcriptase","Producing PTHrP","Causing chronic gastritis"],"c":0,"t":"Oncogenic Viruses","fb":"HPV E6 degrades p53 and E7 inactivates Rb → loss of tumor-suppressor control.","d":"m"},{"q":"Which agent is correctly matched to its associated cancer? Select all that apply.","a":["HBV/HCV → hepatocellular carcinoma","EBV → Burkitt/Hodgkin lymphoma","H. pylori → gastric adenocarcinoma / MALT lymphoma","HPV → osteosarcoma"],"c":0,"t":"Oncogenic Viruses","fb":"HBV/HCV→liver, EBV→lymphomas/nasopharyngeal, H. pylori→gastric. HPV is linked to cervical/oropharyngeal/anal, not bone.","d":"m"},{"q":"Which features are common in CHILDHOOD cancer? Select all that apply.","a":["Rapid growth and short latency","More embryonal tumor types","Links to congenital disorders","Mostly epithelial carcinomas"],"c":0,"t":"Pediatric Cancer","fb":"Pediatric cancers are embryonal/mesenchymal with short latency and congenital links; epithelial carcinomas are rare.","d":"m"},{"q":"The MOST COMMON childhood cancer overall is:","a":["Leukemia (especially ALL)","Breast cancer","Colorectal cancer","Melanoma"],"c":0,"t":"Pediatric Cancer","fb":"Leukemia (especially ALL) is the most common pediatric cancer; CNS tumors are second.","d":"m"},{"q":"Which local effect of a tumor results from a bone metastasis?","a":["Pathologic fracture and hypercalcemia","Jaundice","Airway obstruction","Hydronephrosis"],"c":0,"t":"Local Effects","fb":"Bone mets destroy bone → pathologic fractures and release calcium → hypercalcemia.","d":"m"},{"q":"A tumor compressing the bile duct produces which local effect?","a":["Jaundice (biliary obstruction)","Bowel obstruction","Post-obstructive pneumonia","Hematuria"],"c":0,"t":"Local Effects","fb":"Biliary obstruction by tumor mass causes jaundice.","d":"m"},{"q":"Cancer cachexia is BEST described as:","a":["Progressive weight loss and muscle wasting despite adequate intake","Weight gain from fluid retention","A reversible nutritional deficiency cured by feeding","Loss of fat only, with preserved muscle"],"c":0,"t":"Systemic Effects","fb":"Cachexia is cytokine-driven wasting (TNF-alpha, IL-6) that persists despite adequate intake.","d":"m"},{"q":"Which mechanisms explain cancer cachexia? Select all that apply.","a":["Inflammatory cytokines increase","Tumor energy use is altered","Muscle protein breakdown rises","Resting energy demand increases"],"c":0,"t":"Systemic Effects","fb":"All four contribute; insulin action does NOT become stronger in cachexia.","d":"m"},{"q":"In a neutropenic cancer patient, fever is treated as an emergency because:","a":["Febrile neutropenia can rapidly progress to life-threatening infection","Fever indicates tumor shrinkage","It is always a benign drug reaction","Neutropenia protects against infection"],"c":0,"t":"Systemic Effects","fb":"With ANC < 500 and fever, blood cultures plus broad-spectrum antibiotics are needed within ~1 hour.","d":"m"},{"q":"SIADH and ectopic ACTH (Cushing) as paraneoplastic syndromes are classically associated with:","a":["Small-cell lung cancer","Renal cell carcinoma","Colon cancer","Melanoma"],"c":0,"t":"Paraneoplastic","fb":"Small-cell lung cancer classically secretes ectopic ADH (SIADH) and ACTH (Cushing).","d":"m"},{"q":"Hypercalcemia of malignancy is most often caused by tumor secretion of:","a":["PTHrP (parathyroid hormone-related protein)","Erythropoietin","ADH","Insulin"],"c":0,"t":"Paraneoplastic","fb":"PTHrP (e.g., squamous cell lung cancer) and bone mets raise serum calcium.","d":"m"},{"q":"Match paraneoplastic syndromes to their secreted substance. Which are correct? Select all that apply.","a":["Polycythemia — ectopic erythropoietin","Hypercalcemia — PTHrP","SIADH — ectopic ADH","Cushing — ectopic insulin"],"c":0,"t":"Paraneoplastic","fb":"Cushing syndrome is ectopic ACTH (not insulin). The other three pairings are correct.","d":"m"},{"q":"Tumor lysis syndrome (TLS) classically produces which lab pattern?","a":["High K+, high phosphate, high uric acid, LOW calcium","Low K+, high calcium","High sodium, low phosphate","High calcium, low uric acid"],"c":0,"t":"Oncologic Emergencies","fb":"Rapid cell breakdown dumps K+, phosphate, and uric acid into blood; calcium falls. Risk: arrhythmia, AKI, seizures.","d":"m"},{"q":"Superior vena cava (SVC) syndrome presents with:","a":["Facial and arm swelling, distended neck veins, and dyspnea","High potassium and low calcium","Sudden bone fracture","Severe diarrhea"],"c":0,"t":"Oncologic Emergencies","fb":"Tumor compression of the SVC impairs venous return → facial/arm edema, JVD, dyspnea.","d":"m"},{"q":"A cancer patient with new back pain plus leg weakness and bowel/bladder changes needs emergent evaluation for:","a":["Spinal cord compression (urgent MRI, steroids, radiation)","Routine outpatient physical therapy","Iron-deficiency anemia workup only","Elective imaging in 6 weeks"],"c":0,"t":"Oncologic Emergencies","fb":"Back pain + new neuro deficit + sphincter change = cord compression — an oncologic emergency.","d":"m"},{"q":"First-line management of tumor lysis syndrome includes which measures? Select all that apply.","a":["Aggressive IV hydration","Allopurinol or rasburicase to lower uric acid","Correcting electrolyte abnormalities","Withholding all fluids"],"c":0,"t":"Oncologic Emergencies","fb":"TLS treatment: hydrate, lower uric acid (allopurinol/rasburicase), correct electrolytes. Withholding fluids is wrong.","d":"m"},{"q":"In the TNM staging system, the letters T, N, and M stand for:","a":["Tumor size/extent, regional lymph Nodes, distant Metastasis","Type, Number, and Mutation","Tissue, Node, and Mass","Tumor grade, Necrosis, and Mitosis"],"c":0,"t":"Carcinogenesis Stages","fb":"TNM: T = primary tumor size/extent, N = regional lymph-node involvement, M = distant metastasis.","d":"m"},{"q":"A tumor that spreads to distant organs is called ___.","a":["Malignant","Benign","Encapsulated","Dormant"],"c":0,"t":"Benign vs Malignant","fb":"Spread (metastasis) is a malignant behavior.","d":"e"},{"q":"A malignant tumor of epithelial tissue is a ___.","a":["Carcinoma","Sarcoma","Adenoma","Lipoma"],"c":0,"t":"Tumor Nomenclature","fb":"Epithelial malignancies are carcinomas.","d":"e"},{"q":"Which tumor-suppressor gene is the 'guardian of the genome'?","a":["TP53","KRAS","HER2","BCR-ABL"],"c":0,"t":"Tumor Suppressors","fb":"TP53 is mutated in >50% of cancers.","d":"e"},{"q":"The most preventable cause of cancer is ___.","a":["Tobacco","Sunlight","Coffee","Exercise"],"c":0,"t":"Risk Factors","fb":"Tobacco is the single largest preventable cause.","d":"e"},{"q":"VEGF helps a tumor by promoting ___.","a":["New blood vessel growth (angiogenesis)","Cell death","Immune attack","DNA repair"],"c":0,"t":"Angiogenesis/Metastasis","fb":"VEGF drives angiogenesis to feed the tumor.","d":"e"},{"q":"The most common cancer in children is ___.","a":["Leukemia","Breast cancer","Colon cancer","Lung cancer"],"c":0,"t":"Pediatric Cancer","fb":"Leukemia (especially ALL) is the most common pediatric cancer.","d":"e"},{"q":"HPV is most associated with which cancer?","a":["Cervical","Bone","Skin","Brain"],"c":0,"t":"Oncogenic Viruses","fb":"High-risk HPV causes cervical (and oropharyngeal/anal) cancer.","d":"e"},{"q":"Benign tumors usually do NOT ___.","a":["Metastasize","Grow","Have cells","Form a mass"],"c":0,"t":"Benign vs Malignant","fb":"Benign tumors do not spread to distant sites.","d":"e"},{"q":"Cancer is the #__ cause of death in U.S. adults.","a":["2","1","5","10"],"c":0,"t":"Epidemiology","fb":"Cancer is second only to heart disease.","d":"e"},{"q":"Cachexia refers to severe ___.","a":["Weight loss and muscle wasting","Weight gain","Swelling","Bleeding"],"c":0,"t":"Systemic Effects","fb":"Cachexia is cytokine-driven wasting.","d":"e"},{"q":"A bone tumor in a teenager is diagnosed as osteosarcoma. Its tissue of origin and behavior are:","a":["Mesenchymal (connective) tissue; malignant","Epithelial; benign","Hematopoietic; benign","Neural; benign"],"c":0,"t":"Tumor Nomenclature","fb":"'Sarcoma' = malignant mesenchymal tumor; osteosarcoma arises from bone.","d":"m"},{"q":"A patient is told a glandular tumor is an 'adenocarcinoma' rather than an 'adenoma.' This means it is:","a":["Malignant (cancerous)","Benign","Non-growing","A blood cancer"],"c":0,"t":"Tumor Nomenclature","fb":"'-carcinoma' denotes a malignant epithelial tumor; 'adenoma' is benign.","d":"m"},{"q":"HER2 overexpression in breast cancer drives which hallmark of cancer?","a":["Sustained proliferative signaling","Resisting apoptosis","Inducing angiogenesis","Genome instability"],"c":0,"t":"Hallmarks of Cancer","fb":"HER2 (a growth receptor) keeps proliferative signaling switched on.","d":"m"},{"q":"A cancer cell reactivates telomerase. Which hallmark does this enable?","a":["Replicative immortality","Evading immune destruction","Reprogrammed metabolism","Inducing angiogenesis"],"c":0,"t":"Hallmarks of Cancer","fb":"Telomerase prevents telomere shortening → limitless replication.","d":"m"},{"q":"A KRAS point mutation contributes to cancer by:","a":["Converting a proto-oncogene into an active oncogene","Repairing DNA","Activating a tumor suppressor","Increasing apoptosis"],"c":0,"t":"Oncogenes","fb":"A gain-of-function point mutation activates KRAS as an oncogene.","d":"m"},{"q":"Retinoblastoma classically demonstrates which concept of tumor-suppressor genes?","a":["Knudson's two-hit hypothesis (RB)","Single-hit oncogene activation","Epigenetic-only silencing","Viral integration"],"c":0,"t":"Tumor Suppressors","fb":"RB loss requires both alleles to be inactivated — the two-hit hypothesis.","d":"m"},{"q":"A woman with a BRCA1 mutation is counseled that she is at increased risk for:","a":["Breast and ovarian cancer","Only skin cancer","Only leukemia","No increased risk"],"c":0,"t":"Tumor Suppressors","fb":"BRCA1/2 mutations markedly raise breast and ovarian cancer risk.","d":"m"},{"q":"Breast cancer most commonly metastasizes to which sites? Select all that apply.","a":["Bone","Lung","Liver","Stomach lining only"],"c":0,"t":"Angiogenesis/Metastasis","fb":"Common metastatic sites are bone, lung, liver, and brain ('seed and soil').","d":"m"},{"q":"The most commonly diagnosed cancer (incidence) in U.S. MEN is:","a":["Prostate","Lung","Colon","Pancreatic"],"c":0,"t":"Epidemiology","fb":"Prostate is the most common cancer by incidence in men; lung is the deadliest.","d":"m"},{"q":"The most commonly diagnosed cancer (incidence) in U.S. WOMEN is:","a":["Breast","Lung","Colon","Cervical"],"c":0,"t":"Epidemiology","fb":"Breast cancer is the most common cancer by incidence in women.","d":"m"},{"q":"The HPV vaccine most directly reduces the risk of which cancer?","a":["Cervical","Bone","Brain","Stomach"],"c":0,"t":"Risk Factors","fb":"HPV vaccination prevents high-risk HPV infection → lowers cervical (and other) cancer risk.","d":"m"},{"q":"Aflatoxin (a mold toxin on stored grains) is a chemical carcinogen linked to:","a":["Hepatocellular carcinoma","Melanoma","Cervical cancer","Leukemia"],"c":0,"t":"Carcinogens","fb":"Aflatoxin is a classic chemical carcinogen causing liver cancer.","d":"m"},{"q":"Epstein-Barr virus (EBV) is associated with which malignancy?","a":["Burkitt lymphoma","Cervical cancer","Hepatocellular carcinoma","Gastric MALT lymphoma"],"c":0,"t":"Oncogenic Viruses","fb":"EBV is linked to Burkitt/Hodgkin lymphoma and nasopharyngeal carcinoma.","d":"m"},{"q":"A patient with small-cell lung cancer develops confusion and low serum sodium. The likely paraneoplastic syndrome is:","a":["SIADH (ectopic ADH)","Hypercalcemia of malignancy","Polycythemia","Lambert-Eaton"],"c":0,"t":"Paraneoplastic","fb":"Small-cell lung cancer can secrete ectopic ADH → SIADH/hyponatremia.","d":"m"},{"q":"A patient with squamous-cell lung cancer has a high calcium level from tumor-secreted PTHrP. This is:","a":["Hypercalcemia of malignancy","SIADH","Cushing syndrome","Polycythemia"],"c":0,"t":"Paraneoplastic","fb":"PTHrP secretion raises calcium = hypercalcemia of malignancy.","d":"m"},{"q":"Hours after starting chemotherapy for leukemia, labs show high potassium, high phosphate, high uric acid, and low calcium. This is:","a":["Tumor lysis syndrome","SVC syndrome","Spinal cord compression","Febrile neutropenia"],"c":0,"t":"Oncologic Emergencies","fb":"Rapid tumor cell breakdown releases K+, phosphate, and uric acid → TLS.","d":"m"},{"q":"A patient with a mediastinal tumor has facial swelling, distended neck veins, and dyspnea. This is:","a":["Superior vena cava (SVC) syndrome","Tumor lysis syndrome","Spinal cord compression","Hypercalcemia"],"c":0,"t":"Oncologic Emergencies","fb":"SVC compression impairs venous return → facial/arm edema, JVD, dyspnea.","d":"m"},{"q":"A colon tumor causes crampy pain, distension, and no stool passage. This local effect is:","a":["Bowel obstruction","Jaundice","Post-obstructive pneumonia","Hydronephrosis"],"c":0,"t":"Local Effects","fb":"A luminal tumor can obstruct the bowel → obstruction symptoms.","d":"m"},{"q":"A toddler presents with a large, firm abdominal (kidney) mass; biopsy shows an embryonal tumor. This is most likely:","a":["Wilms tumor (nephroblastoma)","Adenocarcinoma","Squamous cell carcinoma","Mesothelioma"],"c":0,"t":"Pediatric Cancer","fb":"Wilms tumor is a common embryonal kidney cancer of young children.","d":"m"},{"q":"A chemotherapy patient with ANC < 500 spikes a fever. The priority is:","a":["Blood cultures and broad-spectrum antibiotics within ~1 hour","Routine outpatient follow-up","Withhold all treatment","Give acetaminophen and wait"],"c":0,"t":"Systemic Effects","fb":"Febrile neutropenia is an emergency requiring prompt cultures and antibiotics.","d":"m"}]},"4":{"title":"Week 4 — Neurological Disorders","slides":{"Neuro Cells & Glia":"9","Myelin & Conduction":"10","Brain Anatomy":"11, 13","Cranial Nerves":"14","CSF & Ventricles":"12","Pain":"17–19","Sensory Tracts":"20","Arousal & Sleep":"21–22","Cerebral Hemodynamics":"27","Increased ICP":"28","Herniation":"29","UMN vs LMN":"30","Parkinson Disease":"31","Multiple Sclerosis":"32","ALS":"33","Stroke":"34","Traumatic Brain Injury":"35"},"questions":[{"q":"Which glial cell forms myelin in the CENTRAL nervous system?","a":["Oligodendrocyte","Schwann cell","Astrocyte","Microglia"],"c":0,"t":"Neuro Cells & Glia","fb":"Oligodendrocytes myelinate CNS axons; Schwann cells myelinate the PNS.","d":"m"},{"q":"Match glial cells to function. Which are correct? Select all that apply.","a":["Astrocytes support the blood–brain barrier","Microglia provide CNS immune defense","Schwann cells myelinate peripheral nerves","Oligodendrocytes myelinate peripheral nerves"],"c":0,"t":"Neuro Cells & Glia","fb":"Oligodendrocytes myelinate the CNS (not PNS). The other three are correct.","d":"m"},{"q":"Saltatory conduction refers to action potentials:","a":["Jumping node-to-node along myelinated axons (much faster)","Moving backward along the axon","Traveling only in unmyelinated fibers","Stopping at each node permanently"],"c":0,"t":"Myelin & Conduction","fb":"Myelin lets impulses leap between nodes of Ranvier, greatly speeding conduction.","d":"m"},{"q":"A patient with a demyelinating disorder has delayed voluntary movement because of:","a":["Slower impulse conduction from loss of saltatory conduction","Reduced neurotransmitter release","Poor membrane ion exchange","Reduced cerebral blood flow"],"c":0,"t":"Myelin & Conduction","fb":"Demyelination disrupts node-to-node jumping → slowed conduction and motor/sensory deficits.","d":"m"},{"q":"Which brain structure is the body's homeostatic control center (temperature, hunger, hormones, circadian rhythm)?","a":["Hypothalamus","Cerebellum","Occipital lobe","Medulla"],"c":0,"t":"Brain Anatomy","fb":"The hypothalamus governs temperature, appetite, hormone release, and circadian rhythm.","d":"m"},{"q":"The cerebellum is chiefly responsible for:","a":["Coordination, balance, and fine-motor control","Vision","Language comprehension","Hormone secretion"],"c":0,"t":"Brain Anatomy","fb":"The cerebellum coordinates movement and balance; damage causes ataxia.","d":"m"},{"q":"Broca's area (speech production) is located in which lobe?","a":["Frontal","Temporal","Occipital","Parietal"],"c":0,"t":"Brain Anatomy","fb":"Broca's area (speech production) is frontal; Wernicke's area (comprehension) is temporal.","d":"m"},{"q":"Damage to the occipital lobe most directly impairs:","a":["Vision","Hearing","Voluntary movement","Smell"],"c":0,"t":"Brain Anatomy","fb":"The occipital lobe houses the visual cortex.","d":"m"},{"q":"Cerebrospinal fluid is produced by the ___ and reabsorbed by the ___.","a":["Choroid plexus; arachnoid villi","Arachnoid villi; choroid plexus","Thalamus; pia mater","Pituitary; dura mater"],"c":0,"t":"CSF & Ventricles","fb":"Choroid plexus makes CSF; arachnoid villi return it to venous blood. Blockage → hydrocephalus and ↑ICP.","d":"m"},{"q":"Cranial nerve III (oculomotor) compression, as in uncal herniation, classically causes:","a":["A fixed, dilated pupil","Facial droop","Tongue deviation","Hearing loss"],"c":0,"t":"Cranial Nerves","fb":"CN III controls the pupil; compression → a fixed, dilated pupil (a herniation warning sign).","d":"m"},{"q":"Which cranial nerve, when damaged, produces facial droop (Bell's palsy or stroke)?","a":["CN VII (facial)","CN V (trigeminal)","CN II (optic)","CN XII (hypoglossal)"],"c":0,"t":"Cranial Nerves","fb":"CN VII controls facial expression; lesions cause facial droop.","d":"m"},{"q":"The spinothalamic tract carries which sensations, and where does it cross?","a":["Pain and temperature; crosses at the spinal cord level (contralateral)","Fine touch and vibration; crosses at the medulla","Unconscious proprioception; does not cross","Motor commands; crosses at the cortex"],"c":0,"t":"Sensory Tracts","fb":"Spinothalamic = pain/temperature, crossing at the cord (so deficits are contralateral below the lesion).","d":"m"},{"q":"The dorsal column / medial lemniscus pathway carries:","a":["Fine touch, vibration, and proprioception","Pain and temperature","Motor output to muscles","Autonomic signals only"],"c":0,"t":"Sensory Tracts","fb":"Dorsal columns carry fine touch, vibration, and proprioception, crossing at the medulla.","d":"m"},{"q":"Brown-Séquard (cord hemisection) syndrome produces:","a":["Ipsilateral motor/proprioception loss with contralateral pain/temperature loss below the lesion","Bilateral loss of all sensation","Loss of vision only","Pure motor weakness with intact reflexes"],"c":0,"t":"Sensory Tracts","fb":"Because tracts cross at different points, hemisection gives ipsilateral motor/proprioception and contralateral pain/temp loss.","d":"m"},{"q":"Neuropathic pain is BEST described as:","a":["Burning, shooting pain from damage/dysfunction of the nervous system itself","Sharp, well-localized pain from skin or bone injury","Cramping pain from a hollow organ","Pain only during active inflammation"],"c":0,"t":"Pain","fb":"Neuropathic pain (burning, electric, allodynia) arises from nerve dysfunction, not tissue injury; treated with gabapentin, TCAs, SNRIs.","d":"m"},{"q":"A patient reports burning, shooting pain months after a nerve injury with no new tissue damage. This is:","a":["Neuropathic pain from abnormal nerve signaling","Nociceptive pain from activated receptors","Referred pain","Acute inflammatory pain"],"c":0,"t":"Pain","fb":"Pain from disordered nerve signaling (ectopic discharge, central sensitization) = neuropathic.","d":"m"},{"q":"Visceral nociceptive pain is typically:","a":["Poorly localized, cramping, and often referred","Sharp and precisely localized","Always burning and electric","Felt only at the skin surface"],"c":0,"t":"Pain","fb":"Visceral pain is diffuse/cramping and often referred (e.g., cardiac pain to the left arm/jaw).","d":"m"},{"q":"Injury to the Reticular Activating System (RAS) characteristically causes:","a":["Coma / impaired arousal","Loss of vision","Spastic paralysis","Loss of fine touch"],"c":0,"t":"Arousal & Sleep","fb":"The RAS (brainstem) drives wakefulness/arousal; injury can produce coma.","d":"m"},{"q":"Which part of the hypothalamus drives the circadian rhythm?","a":["Suprachiasmatic nucleus","Substantia nigra","Choroid plexus","Arachnoid villi"],"c":0,"t":"Arousal & Sleep","fb":"The suprachiasmatic nucleus is the master circadian clock.","d":"m"},{"q":"Hypothalamic damage that abolishes temperature regulation results in:","a":["Poikilothermia (inability to regulate body temperature)","Permanent fever from infection","Increased shivering only","No change in temperature control"],"c":0,"t":"Arousal & Sleep","fb":"The hypothalamus is the thermostat; damage → poikilothermia.","d":"m"},{"q":"Cerebral perfusion pressure (CPP) is calculated as:","a":["CPP = MAP − ICP","CPP = ICP − MAP","CPP = MAP + ICP","CPP = CBF × MAP"],"c":0,"t":"Cerebral Hemodynamics","fb":"CPP = MAP − ICP; target > 60 mmHg. Rising ICP lowers CPP and threatens perfusion.","d":"m"},{"q":"How does CO2 affect cerebral blood flow?","a":["Hypercapnia (high CO2) causes vasodilation and increased CBF","High CO2 causes vasoconstriction","CO2 has no effect on cerebral vessels","Low CO2 increases CBF"],"c":0,"t":"Cerebral Hemodynamics","fb":"High CO2 dilates cerebral vessels (↑CBF); hyperventilation lowers CO2 to transiently reduce ICP.","d":"m"},{"q":"Cerebral autoregulation maintains constant blood flow across which MAP range?","a":["Approximately 50–150 mmHg","20–40 mmHg","150–200 mmHg","It does not vary with MAP"],"c":0,"t":"Cerebral Hemodynamics","fb":"Autoregulation holds CBF steady from MAP ~50–150 mmHg; it is lost in severe brain injury.","d":"m"},{"q":"The Monro–Kellie doctrine states that within the rigid skull:","a":["Brain + blood + CSF are a fixed total volume; an increase in one requires a decrease in another","ICP never changes","CSF can expand the skull","Blood volume is irrelevant to ICP"],"c":0,"t":"Increased ICP","fb":"Because volume is fixed, a growing mass/edema must be offset by less CSF/blood — until compensation fails and ICP rises.","d":"m"},{"q":"Cushing's triad — a LATE sign of increased ICP — consists of:","a":["Bradycardia, hypertension (widened pulse pressure), and irregular respirations","Tachycardia, hypotension, and rapid breathing","Fever, rash, and seizures","Hypotension, bradypnea, and warm skin"],"c":0,"t":"Increased ICP","fb":"Cushing's triad signals impending herniation: bradycardia + hypertension + irregular respirations.","d":"m"},{"q":"A head-injury patient develops bradycardia, widened pulse pressure, and irregular respirations. This indicates:","a":["Increased ICP with brainstem involvement","Reduced cortical blood flow","Diffuse hemispheric swelling without brainstem signs","Ventricular enlargement from excess fluid"],"c":0,"t":"Increased ICP","fb":"This is Cushing's triad — rising ICP compressing the brainstem; a neurosurgical emergency.","d":"m"},{"q":"Which are EARLY signs of increased intracranial pressure? Select all that apply.","a":["Headache","Vomiting","Papilledema","Cushing's triad"],"c":0,"t":"Increased ICP","fb":"Early: headache, vomiting, papilledema, altered consciousness. Cushing's triad is a LATE/ominous sign.","d":"m"},{"q":"Uncal herniation classically produces which hallmark finding?","a":["A fixed, dilated IPSILATERAL pupil (CN III compression)","Bilateral pinpoint pupils","Sudden blindness","Tongue deviation"],"c":0,"t":"Herniation","fb":"The uncus compresses CN III → ipsilateral fixed, dilated pupil — a neurosurgical emergency.","d":"m"},{"q":"Tonsillar herniation (cerebellar tonsils through the foramen magnum) is dangerous because it causes:","a":["Medullary compression → respiratory arrest","Loss of vision only","A lucid interval","Facial droop only"],"c":0,"t":"Herniation","fb":"Tonsillar herniation compresses the medulla (respiratory centers) → respiratory arrest.","d":"m"},{"q":"Which findings indicate an UPPER motor neuron lesion? Select all that apply.","a":["Spasticity","Hyperreflexia","Positive Babinski sign","Muscle fasciculations"],"c":0,"t":"UMN vs LMN","fb":"UMN: spasticity, hyperreflexia, Babinski, little atrophy. Fasciculations/atrophy/hyporeflexia are LMN signs.","d":"m"},{"q":"A lower motor neuron lesion classically produces:","a":["Flaccid paralysis, atrophy, hyporeflexia, and fasciculations","Spasticity and hyperreflexia","A positive Babinski with no atrophy","Intact strength with brisk reflexes"],"c":0,"t":"UMN vs LMN","fb":"LMN lesions cause flaccid weakness, atrophy, decreased reflexes, and fasciculations.","d":"m"},{"q":"Parkinson's disease results from loss of dopaminergic neurons in the:","a":["Substantia nigra","Cerebellum","Hippocampus","Choroid plexus"],"c":0,"t":"Parkinson Disease","fb":"Nigral dopamine loss disrupts the basal ganglia motor circuit; acetylcholine becomes relatively dominant.","d":"m"},{"q":"The cardinal motor signs of Parkinson's disease (TRAP) include which features? Select all that apply.","a":["Resting tremor","Cogwheel rigidity","Bradykinesia/akinesia","Postural instability"],"c":0,"t":"Parkinson Disease","fb":"TRAP: Tremor (resting), Rigidity, Akinesia/bradykinesia, Postural instability.","d":"m"},{"q":"A Parkinson's patient has slowed movement initiation. The underlying change is:","a":["Loss of dopamine disrupts signaling in motor pathways","Loss of myelin slows conduction","Reduced cerebral blood flow","Loss of coordination from cerebellar damage"],"c":0,"t":"Parkinson Disease","fb":"Dopamine depletion in the substantia nigra impairs basal ganglia motor signaling.","d":"m"},{"q":"The first-line (gold-standard) pharmacologic treatment for Parkinson's disease is:","a":["Levodopa/carbidopa","Riluzole","Gabapentin","Insulin"],"c":0,"t":"Parkinson Disease","fb":"Levodopa/carbidopa replenishes dopamine and is the gold-standard treatment.","d":"m"},{"q":"Multiple sclerosis is characterized by:","a":["Autoimmune destruction of CNS myelin with relapsing-remitting deficits","Peripheral nerve demyelination only","Loss of dopaminergic neurons","Degeneration of motor neurons with preserved sensation"],"c":0,"t":"Multiple Sclerosis","fb":"MS = autoimmune CNS demyelination (oligodendrocyte damage, plaques); most commonly relapsing-remitting.","d":"m"},{"q":"Which is the PERIPHERAL counterpart demyelinating disorder distinguished from MS?","a":["Guillain-Barré syndrome","ALS","Parkinson's disease","Alzheimer disease"],"c":0,"t":"Multiple Sclerosis","fb":"MS affects CNS myelin; Guillain-Barré is the peripheral demyelinating disorder.","d":"m"},{"q":"Amyotrophic lateral sclerosis (ALS) is characterized by:","a":["Degeneration of BOTH upper and lower motor neurons with preserved sensation","Sensory loss with preserved strength","CNS demyelination","Dopamine deficiency"],"c":0,"t":"ALS","fb":"ALS degenerates upper AND lower motor neurons; sensation is preserved. Median survival ~3–5 years.","d":"m"},{"q":"Which medication modestly slows ALS progression by reducing glutamate excitotoxicity?","a":["Riluzole","Levodopa","Gabapentin","Carbidopa"],"c":0,"t":"ALS","fb":"Riluzole (a glutamate blocker) modestly slows ALS; there is no cure.","d":"m"},{"q":"Most strokes are which type?","a":["Ischemic (~87%)","Hemorrhagic","Subarachnoid only","Venous"],"c":0,"t":"Stroke","fb":"About 87% of strokes are ischemic (thrombosis, embolism, hypoperfusion).","d":"m"},{"q":"The ischemic 'penumbra' refers to:","a":["Ischemic but still salvageable tissue surrounding the core (the target of tPA)","Dead tissue that cannot recover","Normal brain tissue","A type of hemorrhage"],"c":0,"t":"Stroke","fb":"The penumbra is at-risk but salvageable tissue — the rationale for rapid reperfusion (tPA).","d":"m"},{"q":"Which are causes of HEMORRHAGIC stroke? Select all that apply.","a":["Hypertension","Aneurysm rupture","Arteriovenous malformation (AVM)","Cardiac embolism from atrial fibrillation"],"c":0,"t":"Stroke","fb":"Hemorrhagic strokes come from HTN, aneurysm, or AVM rupture. Embolism causes ISCHEMIC stroke.","d":"m"},{"q":"The FAST acronym for stroke recognition stands for:","a":["Face drooping, Arm weakness, Speech difficulty, Time to call 911","Fever, Ataxia, Seizure, Tremor","Fall, Aura, Stiffness, Tingling","Focal, Acute, Sudden, Transient"],"c":0,"t":"Stroke","fb":"FAST: Face, Arm, Speech, Time — prompts rapid stroke recognition and 911 activation.","d":"m"},{"q":"An epidural hematoma classically involves which vessel and clinical course?","a":["Arterial (middle meningeal artery) with a lucid interval then rapid deterioration","Venous bridging veins with slow onset","Capillary ooze with no symptoms","The superior sagittal sinus"],"c":0,"t":"Traumatic Brain Injury","fb":"Epidural hematoma = arterial bleed (middle meningeal artery); the classic 'lucid interval' precedes rapid decline.","d":"m"},{"q":"A subdural hematoma is typically:","a":["A venous bridging-vein tear, more common in elderly, alcohol use, or anticoagulation","An arterial bleed with a lucid interval","A normal finding after concussion","Caused by the middle meningeal artery"],"c":0,"t":"Traumatic Brain Injury","fb":"Subdural = venous bridging-vein tear; risk rises with brain atrophy (elderly), alcohol, and anticoagulants.","d":"m"},{"q":"Distinguish primary vs secondary TBI. Which statements are correct? Select all that apply.","a":["Primary injury is the direct mechanical damage at impact","Secondary injury develops hours to days later (edema, ischemia, excitotoxicity)","Diffuse axonal injury is a primary injury","Secondary injury occurs instantly at impact"],"c":0,"t":"Traumatic Brain Injury","fb":"Primary = at impact (contusion, DAI); secondary = delayed (edema, ischemia, herniation), which is preventable/treatable.","d":"m"},{"q":"A concussion is best described as:","a":["Temporary neurologic dysfunction with no structural damage, resolving with rest","A permanent arterial hemorrhage","Diffuse axonal injury with coma","A skull fracture with CSF leak"],"c":0,"t":"Traumatic Brain Injury","fb":"Concussion = transient dysfunction without structural injury; managed with rest.","d":"m"},{"q":"Cerebral blood flow below which threshold causes ischemia?","a":["Below ~20 mL/100g/min","Below ~50 mL/100g/min","Below ~60 mL/100g/min","Below ~100 mL/100g/min"],"c":0,"t":"Cerebral Hemodynamics","fb":"Normal CBF is 50–60 mL/100g/min; ischemia occurs < 20 and coma < 10.","d":"m"},{"q":"A patient becomes difficult to arouse after a brainstem injury. Which system is most likely affected?","a":["Reticular Activating System (RAS)","Limbic system","Basal ganglia","Cerebellum"],"c":0,"t":"Arousal & Sleep","fb":"Arousal depends on the brainstem RAS; injury there impairs consciousness.","d":"m"},{"q":"Which acute ICP management measures are appropriate? Select all that apply.","a":["Osmotic therapy (e.g., mannitol/hypertonic saline)","Elevating the head of bed ~30 degrees","Brief hyperventilation to lower CO2","Keeping the patient flat with the head down"],"c":0,"t":"Increased ICP","fb":"Raise HOB ~30°, use osmotic therapy, and briefly hyperventilate; head-down/flat positioning would worsen ICP.","d":"m"},{"q":"Which cell makes myelin in the central nervous system?","a":["Oligodendrocyte","Schwann cell","Neuron","Red blood cell"],"c":0,"t":"Neuro Cells & Glia","fb":"Oligodendrocytes myelinate CNS axons.","d":"e"},{"q":"The cerebellum mainly controls ___.","a":["Balance and coordination","Vision","Hearing","Hormones"],"c":0,"t":"Brain Anatomy","fb":"The cerebellum coordinates movement and balance.","d":"e"},{"q":"Most strokes are which type?","a":["Ischemic","Hemorrhagic","Venous","Traumatic"],"c":0,"t":"Stroke","fb":"About 87% of strokes are ischemic.","d":"e"},{"q":"Parkinson's disease is caused by loss of ___.","a":["Dopamine","Insulin","Myelin","Calcium"],"c":0,"t":"Parkinson Disease","fb":"Loss of dopaminergic neurons in the substantia nigra.","d":"e"},{"q":"Multiple sclerosis attacks ___ in the central nervous system.","a":["Myelin","Bone","Muscle","Blood vessels"],"c":0,"t":"Multiple Sclerosis","fb":"MS is autoimmune demyelination of CNS axons.","d":"e"},{"q":"FAST is a tool to quickly recognize a ___.","a":["Stroke","Seizure","Heart attack","Fracture"],"c":0,"t":"Stroke","fb":"FAST = Face, Arm, Speech, Time.","d":"e"},{"q":"Cerebrospinal fluid (CSF) is produced by the ___.","a":["Choroid plexus","Pituitary","Cerebellum","Spinal nerves"],"c":0,"t":"CSF & Ventricles","fb":"The choroid plexus makes CSF.","d":"e"},{"q":"ALS is a disease of which neurons?","a":["Motor neurons","Sensory neurons only","Glial cells only","Autonomic neurons only"],"c":0,"t":"ALS","fb":"ALS degenerates upper and lower motor neurons.","d":"e"},{"q":"A concussion causes what kind of brain damage?","a":["Temporary, no structural damage","Permanent bleeding","A skull fracture","A brain tumor"],"c":0,"t":"Traumatic Brain Injury","fb":"Concussion = transient dysfunction, resolves with rest.","d":"e"},{"q":"The late triad of rising ICP is named after ___.","a":["Cushing","Parkinson","Wernicke","Babinski"],"c":0,"t":"Increased ICP","fb":"Cushing's triad: bradycardia, hypertension, irregular respirations.","d":"e"},{"q":"A patient with a head injury has a fixed, dilated pupil on one side. Compression of which cranial nerve explains this?","a":["CN III (oculomotor)","CN II (optic)","CN VII (facial)","CN XII (hypoglossal)"],"c":0,"t":"Cranial Nerves","fb":"Uncal herniation compresses CN III → ipsilateral fixed, dilated pupil.","d":"m"},{"q":"A stroke patient has a facial droop. Which cranial nerve controls these muscles of expression?","a":["CN VII (facial)","CN V (trigeminal)","CN III (oculomotor)","CN X (vagus)"],"c":0,"t":"Cranial Nerves","fb":"CN VII drives facial expression; lesions cause droop.","d":"m"},{"q":"A spinal lesion causes loss of pain and temperature on the OPPOSITE side below the lesion. Which tract is involved?","a":["Spinothalamic tract","Dorsal columns","Corticospinal tract","Spinocerebellar tract"],"c":0,"t":"Sensory Tracts","fb":"The spinothalamic tract (pain/temp) crosses at the cord, so deficits are contralateral.","d":"m"},{"q":"Which glial cell repairs and myelinates PERIPHERAL nerves?","a":["Schwann cell","Oligodendrocyte","Astrocyte","Microglia"],"c":0,"t":"Neuro Cells & Glia","fb":"Schwann cells myelinate the PNS; oligodendrocytes handle the CNS.","d":"m"},{"q":"As intracranial pressure rises, cerebral perfusion pressure (CPP = MAP − ICP):","a":["Falls","Rises","Stays the same","Becomes negative immediately"],"c":0,"t":"Cerebral Hemodynamics","fb":"Higher ICP lowers CPP, threatening cerebral perfusion.","d":"m"},{"q":"A patient develops bradycardia, widening pulse pressure, and irregular breathing after a head injury. This triad indicates:","a":["Cushing's triad — impending herniation from high ICP","Septic shock","Hypoglycemia","A normal stress response"],"c":0,"t":"Increased ICP","fb":"Cushing's triad signals dangerously elevated ICP with brainstem compression.","d":"m"},{"q":"Tonsillar herniation through the foramen magnum is immediately life-threatening because it compresses the:","a":["Medulla (respiratory centers)","Frontal lobe","Optic chiasm","Cerebellar cortex only"],"c":0,"t":"Herniation","fb":"Medullary compression causes respiratory arrest.","d":"m"},{"q":"A patient has spasticity, hyperreflexia, and a positive Babinski sign. These indicate a lesion of the:","a":["Upper motor neuron","Lower motor neuron","Peripheral sensory nerve","Neuromuscular junction"],"c":0,"t":"UMN vs LMN","fb":"Spasticity + hyperreflexia + Babinski = UMN signs.","d":"m"},{"q":"A patient has flaccid weakness, muscle atrophy, and fasciculations. These indicate a lesion of the:","a":["Lower motor neuron","Upper motor neuron","Cerebellum","Basal ganglia"],"c":0,"t":"UMN vs LMN","fb":"Flaccidity, atrophy, and fasciculations = LMN signs.","d":"m"},{"q":"A patient has a resting (pill-rolling) tremor, cogwheel rigidity, and slow movement. The cause is loss of dopaminergic neurons in the:","a":["Substantia nigra (Parkinson's)","Hippocampus","Cerebellum","Choroid plexus"],"c":0,"t":"Parkinson Disease","fb":"TRAP features point to Parkinson's disease (nigral dopamine loss).","d":"m"},{"q":"A young adult has episodes of optic neuritis, limb weakness, and numbness that come and go over years. The likely diagnosis is:","a":["Multiple sclerosis","Parkinson's disease","ALS","Myasthenia gravis"],"c":0,"t":"Multiple Sclerosis","fb":"Relapsing-remitting CNS demyelination = MS.","d":"m"},{"q":"A patient has progressive muscle weakness and wasting with fasciculations, but SENSATION is fully preserved. This pattern fits:","a":["Amyotrophic lateral sclerosis (ALS)","Multiple sclerosis","Guillain-Barré","Peripheral neuropathy"],"c":0,"t":"ALS","fb":"ALS degenerates motor neurons (upper and lower) while sparing sensation.","d":"m"},{"q":"In an acute ischemic stroke, the tissue that is at risk but still salvageable (the target of tPA) is the:","a":["Penumbra","Infarct core","Ventricle","Dura"],"c":0,"t":"Stroke","fb":"The penumbra is salvageable tissue surrounding the dead core.","d":"m"},{"q":"Which finding points to a HEMORRHAGIC rather than ischemic stroke cause?","a":["Ruptured aneurysm","Cardiac embolus from atrial fibrillation","Carotid thrombosis","Small-vessel clot"],"c":0,"t":"Stroke","fb":"Aneurysm/AVM/HTN rupture cause hemorrhagic stroke; clots/emboli cause ischemic stroke.","d":"m"},{"q":"A patient hit in the temple has a brief lucid interval, then rapidly deteriorates. CT shows an arterial bleed. This is a(n):","a":["Epidural hematoma","Subdural hematoma","Concussion","Ischemic stroke"],"c":0,"t":"Traumatic Brain Injury","fb":"Epidural hematoma (middle meningeal artery) classically has a lucid interval then decline.","d":"m"},{"q":"An elderly patient on anticoagulants has a slow venous bleed after a minor fall. This is most likely a(n):","a":["Subdural hematoma","Epidural hematoma","Concussion","Tension pneumocephalus"],"c":0,"t":"Traumatic Brain Injury","fb":"Subdural hematoma = bridging-vein tear, common in elderly/anticoagulated patients.","d":"m"},{"q":"A patient describes burning, electric-shock pain after shingles, with no new injury. Which pain type and treatment fit best?","a":["Neuropathic pain; gabapentin or a TCA","Nociceptive pain; an NSAID alone","Referred pain; antibiotics","Acute inflammatory pain; ice only"],"c":0,"t":"Pain","fb":"Postherpetic neuralgia is neuropathic; treated with gabapentin, TCAs, or SNRIs.","d":"m"},{"q":"A brainstem injury leaves a patient difficult to arouse. Which system is most likely affected?","a":["Reticular Activating System","Cerebellum","Basal ganglia","Occipital cortex"],"c":0,"t":"Arousal & Sleep","fb":"The brainstem RAS controls arousal; injury causes decreased consciousness/coma.","d":"m"},{"q":"A stroke patient can understand speech but cannot produce fluent words. Which area is affected?","a":["Broca's area (frontal lobe)","Wernicke's area (temporal lobe)","Occipital cortex","Cerebellum"],"c":0,"t":"Brain Anatomy","fb":"Broca's area (frontal) handles speech production; damage → expressive aphasia.","d":"m"},{"q":"A stroke patient speaks fluently but the words are nonsensical and they cannot comprehend speech. Which area is affected?","a":["Wernicke's area (temporal lobe)","Broca's area (frontal lobe)","Cerebellum","Spinal cord"],"c":0,"t":"Brain Anatomy","fb":"Wernicke's area (temporal) handles comprehension; damage → receptive aphasia.","d":"m"}]},"5":{"title":"Week 5 — Neuro Assessment & Trauma","slides":{"Stroke":"8–9","Stroke Risk Factors":"10","Multiple Sclerosis":"11","Meningitis":"12","Spinal Cord Injury":"13","Neurogenic Shock":"14","Glasgow Coma Scale":"18","Herniated Disk":"19","Burns":"20–21","TBI/ICP":"17","NMJ Anatomy":"26–27","Myasthenia Gravis":"28","NMJ Toxins":"29","Hydrocephalus":"33","Spina Bifida":"34","Pediatric Meningitis":"35","Seizures":"36","Cerebral Palsy":"37"},"questions":[{"q":"A patient suddenly develops right arm weakness and difficulty speaking. The mechanism is:","a":["Decreased cerebral blood flow causing neuronal hypoxia and injury","Increased CSF pressure compressing tissue","Autoimmune destruction of ACh receptors","Peripheral sensory nerve degeneration"],"c":0,"t":"Stroke","fb":"Acute focal deficits (arm weakness, aphasia) reflect ischemic stroke — reduced CBF → neuronal hypoxia.","d":"m"},{"q":"What is the time window for IV tPA in acute ISCHEMIC stroke?","a":["Within 4.5 hours of symptom onset","Within 24 hours","Within 1 week","There is no time limit"],"c":0,"t":"Stroke","fb":"tPA is generally given within 4.5 hours; 'time is brain' — ~1.9 million neurons die per minute.","d":"m"},{"q":"Why is tPA CONTRAINDICATED in hemorrhagic stroke?","a":["It is a thrombolytic and would worsen bleeding","It only works on veins","It raises blood pressure","It causes vasospasm"],"c":0,"t":"Stroke","fb":"tPA dissolves clots; giving it during a bleed worsens hemorrhage. Hemorrhagic stroke needs BP control/surgery, NOT tPA.","d":"m"},{"q":"Which is the MOST significant MODIFIABLE risk factor for stroke?","a":["Hypertension","Age","Family history","Male sex"],"c":0,"t":"Stroke Risk Factors","fb":"Hypertension is the single most significant modifiable stroke risk factor.","d":"m"},{"q":"Which are MODIFIABLE stroke risk factors? Select all that apply.","a":["Hypertension","Tobacco use","Atrial fibrillation","Age"],"c":0,"t":"Stroke Risk Factors","fb":"HTN, smoking, and atrial fibrillation are modifiable; age is non-modifiable.","d":"m"},{"q":"Elevated HDL is considered ___ against stroke.","a":["Protective (it removes excess cholesterol and reduces plaque)","A major risk factor","Neutral","A cause of hemorrhage"],"c":0,"t":"Stroke Risk Factors","fb":"HDL removes excess cholesterol and reduces plaque — a protective factor.","d":"m"},{"q":"Which clinical manifestations are commonly associated with MS? Select all that apply.","a":["Muscle weakness","Blurred vision","Paresthesia","Resting tremor"],"c":0,"t":"Multiple Sclerosis","fb":"MS causes weakness, optic/visual changes, paresthesia, and fatigue. A RESTING tremor points to Parkinson's, not MS.","d":"m"},{"q":"What is the MOST common and disabling symptom of multiple sclerosis?","a":["Fatigue","Resting tremor","Complete paralysis","Hearing loss"],"c":0,"t":"Multiple Sclerosis","fb":"Fatigue is the most common and disabling MS symptom.","d":"m"},{"q":"Meningitis is defined as inflammation of the:","a":["Meninges (dura, arachnoid, pia)","Brain parenchyma only","Spinal motor neurons","Peripheral nerves"],"c":0,"t":"Meningitis","fb":"Meningitis = inflammation of the meninges surrounding the brain and spinal cord.","d":"m"},{"q":"Which is the classic triad of meningitis?","a":["Fever, severe headache, and neck stiffness (meningismus)","Chest pain, cough, and fever","Tremor, rigidity, and bradykinesia","Polyuria, polydipsia, and weight loss"],"c":0,"t":"Meningitis","fb":"Fever + severe headache + nuchal rigidity is the classic meningitis triad (plus photophobia).","d":"m"},{"q":"In BACTERIAL meningitis, the CSF typically shows:","a":["Increased WBCs, increased protein, decreased glucose","Decreased WBCs and high glucose","Normal everything","Increased glucose and low protein"],"c":0,"t":"Meningitis","fb":"Bacterial meningitis CSF: high WBCs, high protein, LOW glucose (bacteria consume glucose).","d":"m"},{"q":"The TOP nursing priority for suspected bacterial meningitis is:","a":["Rapid antibiotic administration with droplet precautions","Scheduling outpatient follow-up","Encouraging bright lights and activity","Withholding antibiotics until all cultures return"],"c":0,"t":"Meningitis","fb":"Give antibiotics without delay and use droplet precautions; do not wait for all results.","d":"m"},{"q":"Place the spinal cord injury SECONDARY cascade in order.","a":["Mechanical injury → reduced blood flow → inflammation → loss of function","Inflammation → mechanical injury → loss of function → ischemia","Loss of function → inflammation → ischemia → mechanical injury","Reduced blood flow → loss of function → mechanical injury → inflammation"],"c":0,"t":"Spinal Cord Injury","fb":"Primary mechanical injury → ischemia → inflammation/edema/free radicals → loss of function below the level.","d":"m"},{"q":"A cervical-level spinal cord injury most threatens which function?","a":["Respiration (diaphragm/intercostals)","Bowel/bladder only","Lower-limb sensation only","Speech production"],"c":0,"t":"Spinal Cord Injury","fb":"High cervical injuries can paralyze respiratory muscles — a life threat.","d":"m"},{"q":"A cervical SCI patient has low BP, slow heart rate, warm/dry skin, and paralysis below the injury. This is:","a":["Neurogenic shock","Hypovolemic shock","Cardiogenic shock","Septic shock"],"c":0,"t":"Neurogenic Shock","fb":"Loss of sympathetic tone → vasodilation with bradycardia and warm skin = neurogenic (distributive) shock.","d":"m"},{"q":"How does neurogenic shock differ from hypovolemic shock on assessment?","a":["Neurogenic shows bradycardia and warm skin; hypovolemic shows tachycardia and cool, pale skin","Both show tachycardia and cool skin","Neurogenic shows fever; hypovolemic shows warm skin","They are clinically identical"],"c":0,"t":"Neurogenic Shock","fb":"Lost sympathetic tone gives neurogenic shock its hallmark bradycardia + warm, dry skin (unlike the tachycardia/cool skin of hypovolemia).","d":"m"},{"q":"Management of neurogenic shock may include which measures? Select all that apply.","a":["IV fluids","Vasopressors such as norepinephrine","Atropine for symptomatic bradycardia","Withholding spinal immobilization"],"c":0,"t":"Neurogenic Shock","fb":"Treat with fluids, vasopressors, and atropine for bradycardia, while MAINTAINING spinal immobilization.","d":"m"},{"q":"The Glasgow Coma Scale assesses which three components?","a":["Eye opening, verbal response, and motor response","Pupil size, gait, and reflexes","Heart rate, blood pressure, and respirations","Sensation, strength, and coordination"],"c":0,"t":"Glasgow Coma Scale","fb":"GCS = Eye (4) + Verbal (5) + Motor (6), total 3–15.","d":"m"},{"q":"A GCS of 8 or less generally indicates:","a":["Severe injury and the threshold for intubation","Mild injury, safe for discharge","Normal neurologic status","A purely psychiatric condition"],"c":0,"t":"Glasgow Coma Scale","fb":"GCS ≤ 8 = severe; airway protection (intubation) is typically indicated. 13–15 mild, 9–12 moderate.","d":"m"},{"q":"A herniated lumbar disk causes pain by:","a":["Nucleus pulposus herniating through the annulus and compressing a spinal nerve root","Destroying cortical motor neurons","Blocking ACh at the neuromuscular junction","Demyelinating CNS axons"],"c":0,"t":"Herniated Disk","fb":"Disk herniation compresses a nerve root → radicular (dermatomal) pain; commonly L4-L5 or L5-S1 (sciatica).","d":"m"},{"q":"Using the Rule of Nines in an adult, the anterior trunk represents what % TBSA?","a":["18%","9%","36%","1%"],"c":0,"t":"Burns","fb":"Adult Rule of Nines: head/neck 9%, each arm 9%, anterior trunk 18%, posterior trunk 18%, each leg 18%, perineum 1%.","d":"m"},{"q":"Per the Parkland formula, half of the calculated 24-hour fluid volume is given:","a":["In the first 8 hours (from the time of the burn)","In the last 8 hours","All at once on arrival","Over the first hour only"],"c":0,"t":"Burns","fb":"Parkland: 4 mL × kg × %TBSA; give half in the first 8 hours (from time of burn), half over the next 16.","d":"m"},{"q":"Which fluid is used for Parkland burn resuscitation, titrated to what endpoint?","a":["Lactated Ringer's, titrated to urine output 0.5–1 mL/kg/hr","Normal saline, titrated to heart rate","D5W, titrated to blood pressure","Albumin, titrated to temperature"],"c":0,"t":"Burns","fb":"LR is standard; titrate to urine output 0.5–1 mL/kg/hr as the resuscitation endpoint.","d":"m"},{"q":"A full-thickness (3rd-degree) burn is characteristically:","a":["Leathery and painLESS due to nerve destruction","Red, dry, and very painful","Blistered and moist","Limited to the epidermis"],"c":0,"t":"Burns","fb":"Full-thickness burns destroy nerve endings → leathery, painless wounds. Partial-thickness (2°) burns blister and are very painful.","d":"m"},{"q":"In burn care, the FIRST priority is:","a":["Airway (especially with inhalation injury)","Pain control","Infection prevention","Nutrition"],"c":0,"t":"Burns","fb":"Priority order: airway → fluids → infection → pain. Inhalation injury causes airway edema above the glottis.","d":"m"},{"q":"Place the five steps of NMJ transmission in order.","a":["AP arrives (Ca2+ influx) → ACh released → receptor binding → contraction → acetylcholinesterase termination","ACh released → AP arrives → contraction → termination → receptor binding","Receptor binding → contraction → ACh released → AP arrives → termination","Contraction → termination → AP arrives → ACh released → receptor binding"],"c":0,"t":"NMJ Anatomy","fb":"AP → Ca2+ influx → ACh release → nicotinic receptor binding → contraction → acetylcholinesterase ends the signal.","d":"m"},{"q":"What terminates the signal at the neuromuscular junction so the muscle can relax?","a":["Acetylcholinesterase degrading ACh in the cleft","Reuptake of calcium into bone","Closure of the optic nerve","Production of more ACh"],"c":0,"t":"NMJ Anatomy","fb":"Acetylcholinesterase rapidly breaks down ACh in the synaptic cleft, ending stimulation.","d":"m"},{"q":"Myasthenia gravis is caused by:","a":["Autoantibodies blocking/destroying nicotinic ACh receptors on the motor end plate","Loss of dopaminergic neurons","Demyelination of CNS axons","Compression of a spinal nerve root"],"c":0,"t":"Myasthenia Gravis","fb":"Anti-AChR antibodies reduce receptor availability → impaired end-plate depolarization and weakness.","d":"m"},{"q":"The hallmark of myasthenia gravis is:","a":["Fatigable weakness that worsens with activity and improves with rest","Weakness that improves with repeated activity","Resting tremor","Sensory loss with normal strength"],"c":0,"t":"Myasthenia Gravis","fb":"Fatigable weakness (worse with use, better with rest) is classic; early signs include ptosis and diplopia.","d":"m"},{"q":"A patient has weakness that worsens with activity, improves with rest, and anti-AChR antibodies. The diagnosis is:","a":["Myasthenia gravis","Parkinson's disease","Multiple sclerosis","Herniated disk"],"c":0,"t":"Myasthenia Gravis","fb":"Autoimmune NMJ disease with fatigable weakness and anti-AChR antibodies = myasthenia gravis.","d":"m"},{"q":"First-line symptomatic treatment of myasthenia gravis is:","a":["Acetylcholinesterase inhibitors (e.g., pyridostigmine)","Levodopa","Riluzole","tPA"],"c":0,"t":"Myasthenia Gravis","fb":"Acetylcholinesterase inhibitors increase ACh at the junction; immunosuppression and thymectomy are added.","d":"m"},{"q":"Botulinum toxin causes paralysis by:","a":["Blocking ACh RELEASE from the presynaptic terminal → flaccid descending paralysis","Inhibiting acetylcholinesterase","Destroying ACh receptors","Demyelinating peripheral nerves"],"c":0,"t":"NMJ Toxins","fb":"Botulinum blocks ACh release → flaccid, descending paralysis (blurred vision, dysphagia, respiratory failure).","d":"m"},{"q":"Organophosphate poisoning affects the NMJ by:","a":["Inhibiting acetylcholinesterase → excess ACh → prolonged stimulation then paralysis","Blocking ACh release","Destroying the motor cortex","Reducing calcium influx"],"c":0,"t":"NMJ Toxins","fb":"Organophosphates block ACh BREAKDOWN, flooding the cleft with ACh (the opposite of botulism's blocked release).","d":"m"},{"q":"Which pearl correctly contrasts the two NMJ toxins?","a":["Botulism = blocked ACh release; organophosphate = blocked ACh breakdown","Both block ACh release","Both block ACh breakdown","Botulism = blocked breakdown; organophosphate = blocked release"],"c":0,"t":"NMJ Toxins","fb":"Botulism blocks RELEASE (too little ACh); organophosphates block BREAKDOWN (too much ACh).","d":"m"},{"q":"Pediatric hydrocephalus is caused by:","a":["Abnormal CSF accumulation in the ventricles → ventricular enlargement and increased ICP","Loss of spinal motor neurons","Dopamine deficiency","Peripheral nerve demyelination"],"c":0,"t":"Hydrocephalus","fb":"CSF buildup enlarges ventricles, raising ICP and compressing brain tissue.","d":"m"},{"q":"An infant with rapid head growth, poor feeding, a bulging fontanelle, and downward eye deviation ('sunset sign') most likely has:","a":["Hydrocephalus (CSF buildup enlarging the ventricles)","Spinal motor neuron loss","Dopamine loss","Peripheral demyelination"],"c":0,"t":"Hydrocephalus","fb":"These infant signs reflect rising ICP from hydrocephalus; treated with a VP shunt or ETV.","d":"m"},{"q":"Which neural tube defect is the MOST SEVERE?","a":["Myelomeningocele (cord + meninges protrude)","Spina bifida occulta","Meningocele","None cause deficits"],"c":0,"t":"Spina Bifida","fb":"Myelomeningocele exposes spinal cord and meninges → paralysis and incontinence; occulta is usually asymptomatic.","d":"m"},{"q":"How is neural tube defect risk reduced?","a":["400–800 mcg folic acid daily before conception and through the first trimester","High-dose vitamin A in pregnancy","Avoiding all exercise","Iron supplementation after delivery"],"c":0,"t":"Spina Bifida","fb":"The neural tube closes at weeks 3–4; preconception folic acid (400–800 mcg/day) lowers risk — counseling is key.","d":"m"},{"q":"In a child with meningitis, which finding is a RED FLAG for meningococcemia (an emergency)?","a":["A petechial or purpuric rash","Mild fatigue developing over weeks","A single low-grade temperature","Slight nasal congestion"],"c":0,"t":"Pediatric Meningitis","fb":"A petechial/purpuric rash suggests meningococcemia — a medical emergency requiring immediate treatment.","d":"m"},{"q":"Seizures result fundamentally from:","a":["Excessive, abnormal firing of cortical neurons (too much excitation or too little inhibition)","Increased inhibitory neurotransmission","Loss of myelin in the PNS","Reduced cortical activity"],"c":0,"t":"Seizures","fb":"Seizures = runaway cortical electrical activity from increased excitation or reduced inhibition.","d":"m"},{"q":"During an active seizure, appropriate nursing actions include which of the following? Select all that apply.","a":["Protect the airway","Time the seizure","Pad/clear the environment for safety","Forcefully restrain the patient"],"c":0,"t":"Seizures","fb":"Protect the airway, time it, ensure safety — but do NOT restrain the patient.","d":"m"},{"q":"A febrile seizure classically occurs in which group?","a":["Children ~6 months to 5 years with a rapid fever spike","Adults over 65 with low fevers","Newborns in the first 24 hours","Only children with epilepsy"],"c":0,"t":"Seizures","fb":"Febrile seizures occur in young children (6 mo–5 yr) with rapid temperature rises.","d":"m"},{"q":"Cerebral palsy is best described as:","a":["A NONprogressive motor disorder from early brain injury/malformation","A progressive degenerative disease","A peripheral nerve demyelination","An autoimmune NMJ disorder"],"c":0,"t":"Cerebral Palsy","fb":"CP results from a static (nonprogressive) early brain injury; the brain lesion does not worsen, though function is permanently altered.","d":"m"},{"q":"Which statement about cerebral palsy is TRUE?","a":["The underlying brain injury does not worsen, though function is permanently altered","Children fully recover with physical therapy","It is caused by progressive motor neuron loss","Skills are progressively lost over time"],"c":0,"t":"Cerebral Palsy","fb":"CP is static; therapy can improve function, but progressive loss of skills suggests a different, degenerative disease.","d":"m"},{"q":"Bacterial meningitis is MOST commonly caused by which organisms?","a":["Neisseria meningitidis and Streptococcus pneumoniae","Enteroviruses","Herpes simplex virus","Candida species"],"c":0,"t":"Meningitis","fb":"N. meningitidis and S. pneumoniae are the most common (and severe) bacterial causes; enteroviruses are the most common viral cause.","d":"m"},{"q":"Which secondary mechanisms worsen a traumatic brain injury hours to days later? Select all that apply.","a":["Cerebral edema","Ischemia","Excitotoxicity and free-radical damage","The initial mechanical impact"],"c":0,"t":"TBI/ICP","fb":"Secondary injury (edema, ischemia, excitotoxicity) evolves AFTER impact; the mechanical impact itself is the PRIMARY injury.","d":"m"},{"q":"In pediatric head injury, an early red flag for rising ICP is:","a":["Restlessness and confusion","Improved appetite","Slowed but regular heart rate alone","Decreased head circumference"],"c":0,"t":"TBI/ICP","fb":"In children, new restlessness/confusion can be an early sign of increasing ICP.","d":"m"},{"q":"A motor end-plate disorder produces what pattern of weakness, distinguishing it from cortical disease?","a":["Fatigable muscle weakness without sensory or cortical deficits","Sensory loss with normal strength","Resting tremor","Aphasia and visual field cuts"],"c":0,"t":"NMJ Anatomy","fb":"NMJ pathology causes fatigable weakness; it does not cause resting tremor or cortical (language/vision) deficits.","d":"m"},{"q":"What initiates ACh release at the presynaptic terminal when an action potential arrives?","a":["Opening of voltage-gated calcium channels causing Ca2+ influx","Sodium leaving the cell","Acetylcholinesterase activation","Closure of potassium channels only"],"c":0,"t":"NMJ Anatomy","fb":"Ca2+ influx through voltage-gated channels triggers vesicle fusion and ACh release.","d":"m"},{"q":"Which best explains why 'time is brain' in ischemic stroke?","a":["Roughly 1.9 million neurons die each minute that perfusion is not restored","Neurons regenerate quickly so timing is irrelevant","The penumbra cannot be saved at any time","Brain tissue is resistant to ischemia"],"c":0,"t":"Stroke","fb":"Untreated ischemia kills ~1.9 million neurons/min; rapid reperfusion salvages the penumbra.","d":"m"},{"q":"tPA (clot-buster) is used for which type of stroke?","a":["Ischemic","Hemorrhagic","Both equally","Neither"],"c":0,"t":"Stroke","fb":"tPA dissolves clots in ischemic stroke; never in hemorrhagic.","d":"e"},{"q":"The #1 modifiable risk factor for stroke is ___.","a":["Hypertension","Age","Family history","Sex"],"c":0,"t":"Stroke Risk Factors","fb":"High blood pressure is the most significant modifiable risk.","d":"e"},{"q":"Meningitis is inflammation of the ___.","a":["Meninges","Lungs","Liver","Spinal muscles"],"c":0,"t":"Meningitis","fb":"Meningitis = inflammation of the membranes around the brain/cord.","d":"e"},{"q":"The Glasgow Coma Scale ranges from ___.","a":["3 to 15","0 to 10","1 to 100","5 to 50"],"c":0,"t":"Glasgow Coma Scale","fb":"GCS total is 3 (worst) to 15 (best).","d":"e"},{"q":"Myasthenia gravis attacks which receptors?","a":["Acetylcholine receptors","Dopamine receptors","Insulin receptors","Pain receptors"],"c":0,"t":"Myasthenia Gravis","fb":"Anti-AChR antibodies block the receptors at the NMJ.","d":"e"},{"q":"Botulinum toxin ___ acetylcholine release.","a":["Blocks","Increases","Has no effect on","Reverses"],"c":0,"t":"NMJ Toxins","fb":"Botulism blocks ACh release → flaccid paralysis.","d":"e"},{"q":"In the adult Rule of Nines, the head and neck equal ___ of body surface.","a":["9%","18%","1%","36%"],"c":0,"t":"Burns","fb":"Head & neck = 9% in adults.","d":"e"},{"q":"Taking folic acid in pregnancy helps prevent ___.","a":["Neural tube defects (spina bifida)","Diabetes","Stroke","Cancer"],"c":0,"t":"Spina Bifida","fb":"Folic acid before/early in pregnancy prevents neural tube defects.","d":"e"},{"q":"Hydrocephalus means too much ___ in the brain.","a":["Cerebrospinal fluid","Blood","Air","Muscle"],"c":0,"t":"Hydrocephalus","fb":"Excess CSF enlarges the ventricles and raises ICP.","d":"e"},{"q":"Seizures are caused by abnormal ___ activity in the brain.","a":["Electrical","Hormonal","Muscular","Vascular"],"c":0,"t":"Seizures","fb":"Seizures = excessive abnormal cortical electrical firing.","d":"e"},{"q":"A patient arrives 2 hours after sudden left-sided weakness; CT rules out bleeding. The appropriate therapy is:","a":["IV tPA (within the 4.5-hour window)","Immediate craniotomy","Observation only","tPA only after 24 hours"],"c":0,"t":"Stroke","fb":"Ischemic stroke within 4.5 hours and no hemorrhage → candidate for tPA.","d":"m"},{"q":"Which single intervention most reduces a patient's long-term stroke risk?","a":["Controlling hypertension","Taking vitamin C","Avoiding all exercise","Increasing salt intake"],"c":0,"t":"Stroke Risk Factors","fb":"Hypertension is the leading modifiable stroke risk factor.","d":"m"},{"q":"A child has fever, severe headache, neck stiffness, and photophobia. CSF shows high WBCs, high protein, low glucose. This indicates:","a":["Bacterial meningitis","Viral meningitis with normal glucose","Migraine","Concussion"],"c":0,"t":"Meningitis","fb":"Low CSF glucose with high WBC/protein indicates bacterial meningitis.","d":"m"},{"q":"A patient with suspected meningitis develops a spreading petechial/purpuric rash. This suggests:","a":["Meningococcemia — a medical emergency","A harmless drug rash","Resolving infection","Dehydration only"],"c":0,"t":"Pediatric Meningitis","fb":"A petechial/purpuric rash suggests meningococcemia requiring immediate treatment.","d":"m"},{"q":"A patient with a high cervical spinal cord injury is at greatest immediate risk for:","a":["Respiratory failure (diaphragm involvement)","Bowel changes only","Mild arm weakness only","No serious effects"],"c":0,"t":"Spinal Cord Injury","fb":"High cervical injuries can paralyze respiratory muscles.","d":"m"},{"q":"A trauma patient with a cervical SCI has hypotension, bradycardia, and warm, dry skin. This is:","a":["Neurogenic shock","Hypovolemic shock","Septic shock","Cardiogenic shock"],"c":0,"t":"Neurogenic Shock","fb":"Lost sympathetic tone → vasodilation with bradycardia and warm skin = neurogenic shock.","d":"m"},{"q":"Which finding best distinguishes neurogenic shock from hypovolemic shock?","a":["Bradycardia with warm skin (vs tachycardia with cool skin)","Tachycardia in both","Fever in both","Cool, clammy skin in both"],"c":0,"t":"Neurogenic Shock","fb":"Neurogenic shock uniquely shows bradycardia + warm skin from lost vasomotor/sympathetic tone.","d":"m"},{"q":"A trauma patient has a Glasgow Coma Scale of 7. The priority action is:","a":["Protect/secure the airway (intubation threshold)","Discharge home","Reassess in the morning","No intervention needed"],"c":0,"t":"Glasgow Coma Scale","fb":"GCS ≤ 8 is severe and indicates the need for airway protection.","d":"m"},{"q":"A patient has low back pain radiating down one leg after lifting. Compression of which structure is most likely?","a":["A lumbar spinal nerve root (e.g., L5-S1)","The motor cortex","The neuromuscular junction","The cerebellum"],"c":0,"t":"Herniated Disk","fb":"A herniated disk compresses a nerve root → dermatomal (sciatic) pain.","d":"m"},{"q":"Using the Parkland formula, when is HALF of the 24-hour fluid given to a burn patient?","a":["In the first 8 hours from the time of the burn","In the last 8 hours","All upon arrival","Over the first hour"],"c":0,"t":"Burns","fb":"Parkland: give half the calculated fluid in the first 8 hours (from time of burn).","d":"m"},{"q":"A full-thickness (third-degree) burn is typically:","a":["Leathery and painless (nerve endings destroyed)","Red, dry, and very painful","Blistered and weeping","Limited to the epidermis"],"c":0,"t":"Burns","fb":"Full-thickness burns destroy nerve endings → painless, leathery wounds.","d":"m"},{"q":"In burn care, the FIRST priority — especially with facial burns or soot in the airway — is:","a":["Securing the airway","Pain medication","Wound dressing","Nutrition"],"c":0,"t":"Burns","fb":"Airway first: inhalation injury can cause rapid airway edema.","d":"m"},{"q":"At the neuromuscular junction, the trigger for acetylcholine release when an impulse arrives is:","a":["Calcium influx through voltage-gated channels","Sodium leaving the cell","Acetylcholinesterase","Potassium influx"],"c":0,"t":"NMJ Anatomy","fb":"Ca2+ influx causes vesicle fusion and ACh release.","d":"m"},{"q":"A patient has eyelid drooping and double vision that worsen through the day and improve with rest. The likely diagnosis is:","a":["Myasthenia gravis","Parkinson's disease","Multiple sclerosis","Stroke"],"c":0,"t":"Myasthenia Gravis","fb":"Fatigable weakness (ptosis, diplopia worse with use) = myasthenia gravis.","d":"m"},{"q":"A patient who ate improperly canned food develops descending paralysis and blurred vision. The toxin works by:","a":["Blocking acetylcholine release (botulism)","Inhibiting acetylcholinesterase","Destroying ACh receptors","Demyelinating nerves"],"c":0,"t":"NMJ Toxins","fb":"Botulinum toxin blocks ACh release → flaccid descending paralysis.","d":"m"},{"q":"Organophosphate (pesticide) poisoning causes excessive ACh effects because it:","a":["Inhibits acetylcholinesterase (blocks ACh breakdown)","Blocks ACh release","Destroys the motor cortex","Removes calcium"],"c":0,"t":"NMJ Toxins","fb":"Organophosphates block ACh breakdown, flooding the synapse — opposite of botulism.","d":"m"},{"q":"An infant has a rapidly enlarging head, bulging fontanelle, poor feeding, and downward-deviated eyes. The cause is:","a":["Hydrocephalus (CSF buildup)","Dehydration","Normal growth","Peripheral neuropathy"],"c":0,"t":"Hydrocephalus","fb":"Excess CSF raises ICP → bulging fontanelle, rapid head growth, 'sunset' eyes.","d":"m"},{"q":"Which neural tube defect carries the most severe neurologic impact?","a":["Myelomeningocele","Spina bifida occulta","Meningocele","None cause deficits"],"c":0,"t":"Spina Bifida","fb":"Myelomeningocele exposes the spinal cord → paralysis and incontinence.","d":"m"},{"q":"During a tonic-clonic seizure, the nurse should:","a":["Protect the airway, time the seizure, and keep the patient safe","Forcefully restrain the limbs","Insert a tongue blade","Hold the patient down flat"],"c":0,"t":"Seizures","fb":"Protect, time, and keep safe — never restrain or force objects into the mouth.","d":"m"},{"q":"A child has a nonprogressive motor disorder from a brain injury around birth. Function may improve with therapy but the lesion does not worsen. This is:","a":["Cerebral palsy","Muscular dystrophy","Multiple sclerosis","ALS"],"c":0,"t":"Cerebral Palsy","fb":"Cerebral palsy is a static (nonprogressive) early brain injury.","d":"m"}]},"6":{"title":"Week 6 — The Endocrine System","slides":{"Hormone Classes":"9","Feedback Regulation":"10","HPT Axis":"11","Receptor Regulation":"12, 15","Endocrine Dysfunction Patterns":"13–14","ADH / SIADH / DI":"17–18, 24","Anterior Pituitary":"19","Thyroid Synthesis":"20","Graves Disease":"21","Hashimoto":"22","Thyroid Emergencies":"23","Adrenal Anatomy":"28","Cushing & Addison":"29","Pheochromocytoma":"30","Diabetes Mellitus":"31","DKA":"32","DKA vs HHS":"33","DKA Management":"34"},"questions":[{"q":"Peptide/protein hormones (insulin, GH, ADH, TSH, ACTH) act via:","a":["Cell-surface receptors and second messengers (cAMP, IP3) — fast effects","Intracellular receptors that change gene transcription","Direct entry into the nucleus","No receptor at all"],"c":0,"t":"Hormone Classes","fb":"Water-soluble peptide hormones bind surface receptors and use second messengers for fast effects.","d":"m"},{"q":"Steroid hormones (cortisol, aldosterone, sex steroids) act by:","a":["Binding intracellular/nuclear receptors and altering gene transcription (slow, durable)","Using surface receptors and cAMP","Being degraded before reaching the cell","Blocking acetylcholinesterase"],"c":0,"t":"Hormone Classes","fb":"Lipid-soluble steroids enter the cell and change gene transcription — slow onset but durable effects.","d":"m"},{"q":"Why do thyroid hormones (T3/T4) act 'like steroids' despite being amines?","a":["They are lipid-soluble, enter the cell, and change gene expression","They use only cAMP at the surface","They cannot enter cells","They are peptides"],"c":0,"t":"Hormone Classes","fb":"Thyroid hormones are lipid-soluble amines that enter cells and alter gene expression like steroids.","d":"m"},{"q":"Which is the DOMINANT form of endocrine feedback control?","a":["Negative feedback — rising end-hormone inhibits its releasing/tropic hormones","Positive feedback","Feedforward only","No regulation"],"c":0,"t":"Feedback Regulation","fb":"Negative feedback keeps hormones in range; rising end-hormone suppresses upstream signals.","d":"m"},{"q":"Which are examples of POSITIVE feedback in the endocrine system? Select all that apply.","a":["LH surge before ovulation","Oxytocin release during labor","TSH suppression by high T4","Cortisol suppressing CRH"],"c":0,"t":"Feedback Regulation","fb":"Positive feedback (rare) amplifies output: the ovulatory LH surge and labor oxytocin. The other two are negative feedback.","d":"m"},{"q":"Place the HPT axis in order.","a":["Hypothalamus (TRH) → anterior pituitary (TSH) → thyroid (T3/T4) → negative feedback","Thyroid (TSH) → pituitary (TRH) → hypothalamus (T4)","Pituitary (TRH) → hypothalamus (TSH) → thyroid","Thyroid (T3/T4) → hypothalamus (TSH) → pituitary (TRH)"],"c":0,"t":"HPT Axis","fb":"TRH → TSH → T3/T4, with high T3/T4 feeding back to suppress TRH and TSH.","d":"m"},{"q":"The same axis logic of the HPT applies to which other axes? Select all that apply.","a":["HPA: CRH → ACTH → cortisol","HPG: GnRH → LH/FSH → sex steroids","HPT: TRH → TSH → T3/T4","Renin → angiotensin → ACh"],"c":0,"t":"HPT Axis","fb":"HPA and HPG follow the same hypothalamus→pituitary→target-gland pattern. (RAAS is not an ACh pathway.)","d":"m"},{"q":"Prolonged HIGH hormone levels cause receptor ___, which ___.","a":["Down-regulation; reduces target-cell response at the same hormone concentration","Up-regulation; increases response","No change; keeps response constant","Destruction of the hormone; raises response"],"c":0,"t":"Receptor Regulation","fb":"Chronic high hormone → fewer receptors (down-regulation) → blunted response (e.g., type 2 DM insulin resistance).","d":"m"},{"q":"A patient on a stable hormone dose for months now gets less effect despite elevated hormone levels. The cause is:","a":["Down-regulation of receptors reducing target-cell response","Up-regulation of receptors","Increased receptor affinity","Activity without hormone binding"],"c":0,"t":"Receptor Regulation","fb":"Tachyphylaxis from receptor down-regulation explains reduced effect despite adequate hormone levels.","d":"m"},{"q":"A NORMAL hormone level with NO target-cell response suggests:","a":["A receptor problem (binding defect or receptor resistance)","Gland failure","Excess pituitary hormone","A lab error only"],"c":0,"t":"Receptor Regulation","fb":"Normal hormone + absent response points to a receptor-level defect (resistance/binding problem).","d":"m"},{"q":"Lab pattern HIGH TSH with LOW T4 indicates:","a":["Primary thyroid gland failure (e.g., Hashimoto)","Graves disease","Secondary (pituitary) hypothyroidism","Normal thyroid function"],"c":0,"t":"Endocrine Dysfunction Patterns","fb":"Failing thyroid → low T4; the pituitary compensates by raising TSH = primary gland failure.","d":"m"},{"q":"Lab pattern LOW TSH with HIGH T4 indicates:","a":["Primary gland excess (e.g., Graves) with feedback suppression of TSH","Primary gland failure","Hypopituitarism","Iodine deficiency"],"c":0,"t":"Endocrine Dysfunction Patterns","fb":"Autonomous thyroid hormone production suppresses TSH via negative feedback (Graves).","d":"m"},{"q":"When BOTH TSH and T4 are LOW, the defect is at the level of the:","a":["Pituitary or hypothalamus (secondary/tertiary)","Thyroid gland itself","Target-cell receptor","Kidney"],"c":0,"t":"Endocrine Dysfunction Patterns","fb":"Low pituitary hormone AND low end-hormone = a central (secondary/tertiary) problem driving both down.","d":"m"},{"q":"In untreated Graves disease, the suppressed TSH is explained by:","a":["Increased negative feedback on TRH and TSH from high T3/T4","Increased TRH stimulation","Decreased negative feedback","Pituitary hyperfunction"],"c":0,"t":"Endocrine Dysfunction Patterns","fb":"High circulating T3/T4 strongly suppress TRH and TSH via negative feedback.","d":"m"},{"q":"ADH (antidiuretic hormone) acts on the kidney to:","a":["Insert aquaporins in collecting ducts → reabsorb free water → concentrated urine","Excrete free water → dilute urine","Increase sodium excretion only","Stimulate gluconeogenesis"],"c":0,"t":"ADH / SIADH / DI","fb":"ADH inserts aquaporin channels so the collecting ducts reabsorb water, concentrating the urine.","d":"m"},{"q":"SIADH (too much ADH) produces which lab/clinical picture?","a":["Dilutional hyponatremia, low serum osmolality, concentrated urine","Hypernatremia and dilute urine","High serum osmolality with polyuria","Hyperkalemia with hypotension"],"c":0,"t":"ADH / SIADH / DI","fb":"Excess ADH retains water → dilutional hyponatremia, low serum osmolality, concentrated urine.","d":"m"},{"q":"Diabetes insipidus (too little/ineffective ADH) produces:","a":["Hypernatremia, high serum osmolality, and dilute high-volume urine","Hyponatremia and concentrated urine","Low serum osmolality","Oliguria with weight gain"],"c":0,"t":"ADH / SIADH / DI","fb":"DI = free water loss → hypernatremia, high osmolality, and dilute polyuria with thirst.","d":"m"},{"q":"A lung cancer patient has confusion, low sodium, low osmolality, and concentrated urine. The mechanism is:","a":["Ectopic ADH secretion by malignant pulmonary tumor cells","Loss of hypothalamic ADH only","Renal resistance to ADH","Reduced aquaporin expression"],"c":0,"t":"ADH / SIADH / DI","fb":"Small-cell lung cancer can secrete ectopic ADH → SIADH with dilutional hyponatremia.","d":"m"},{"q":"Which treatments are appropriate for SIADH? Select all that apply.","a":["Fluid restriction","Vaptans (ADH antagonists)","Hypertonic saline if severe/symptomatic","Desmopressin"],"c":0,"t":"ADH / SIADH / DI","fb":"SIADH: restrict fluids, use vaptans, and hypertonic saline if severe. Desmopressin treats central DI (the opposite problem).","d":"m"},{"q":"Central diabetes insipidus is treated with:","a":["Desmopressin (an ADH analog)","Fluid restriction","Vaptans","Insulin"],"c":0,"t":"ADH / SIADH / DI","fb":"Central DI lacks ADH, so desmopressin replaces it; nephrogenic DI may use thiazides.","d":"m"},{"q":"A pituitary adenoma expanding upward classically compresses the optic chiasm, causing:","a":["Bitemporal hemianopia (loss of peripheral vision)","Complete blindness","Tunnel vision sparing the periphery","Loss of smell"],"c":0,"t":"Anterior Pituitary","fb":"Upward pituitary tumor growth compresses the optic chiasm → bitemporal hemianopia.","d":"m"},{"q":"Growth hormone excess from a pituitary adenoma in ADULTS causes:","a":["Acromegaly (enlarged hands, face, jaw)","Gigantism","Dwarfism","Cushing disease"],"c":0,"t":"Anterior Pituitary","fb":"GH excess after growth plates close → acromegaly; before closure (children) → gigantism.","d":"m"},{"q":"Sheehan syndrome (postpartum pituitary infarction) leads to:","a":["Hypopituitarism — multiple tropic hormones fall","Isolated GH excess","Cushing disease","Graves disease"],"c":0,"t":"Anterior Pituitary","fb":"Pituitary damage (Sheehan) reduces TSH, ACTH, LH/FSH, GH — treated with replacement of each deficient axis.","d":"m"},{"q":"Place thyroid hormone synthesis in order.","a":["Iodide uptake → oxidation (thyroid peroxidase) → coupling → storage in colloid → TSH-stimulated release","Coupling → iodide uptake → release → storage → oxidation","Release → storage → coupling → oxidation → uptake","Storage → release → uptake → coupling → oxidation"],"c":0,"t":"Thyroid Synthesis","fb":"Uptake of iodide → TPO oxidation/organification → coupling to T3/T4 → storage in colloid → TSH-triggered release.","d":"m"},{"q":"Graves disease is caused by:","a":["Thyroid-stimulating immunoglobulins (TSI) that mimic TSH at the receptor","Autoimmune destruction of thyroid follicles","Iodine deficiency","Pituitary failure"],"c":0,"t":"Graves Disease","fb":"TSI antibodies stimulate the TSH receptor → autonomous T3/T4 production (hyperthyroidism).","d":"m"},{"q":"Which findings are characteristic of Graves disease? Select all that apply.","a":["Weight loss despite increased appetite","Heat intolerance and palpitations","Exophthalmos","Cold intolerance and weight gain"],"c":0,"t":"Graves Disease","fb":"Graves (hyperthyroid): weight loss, heat intolerance, tachycardia, exophthalmos. Cold intolerance/weight gain are HYPOthyroid features.","d":"m"},{"q":"Hashimoto thyroiditis is characterized by:","a":["Autoimmune destruction of thyroid follicles (anti-TPO) → low T4, high TSH","TSH-receptor stimulation → high T4, low TSH","Excess iodine intake","Pituitary tumor"],"c":0,"t":"Hashimoto","fb":"Hashimoto = autoimmune hypothyroidism: anti-TPO antibodies, low T4 with compensatory high TSH.","d":"m"},{"q":"A patient with fatigue, weight gain, constipation, and cold intolerance has low T4 and high TSH. This reflects:","a":["Primary gland failure due to negative feedback raising TSH","Pituitary hyperfunction with positive feedback","Receptor resistance with a feedforward loop","Ectopic hormone secretion"],"c":0,"t":"Hashimoto","fb":"Failing thyroid (low T4) → pituitary raises TSH (negative feedback) = primary hypothyroidism.","d":"m"},{"q":"The treatment of choice for hypothyroidism (Hashimoto) is:","a":["Levothyroxine (synthetic T4), titrated to a normal TSH","Methimazole","Radioactive iodine","Hydrocortisone alone"],"c":0,"t":"Hashimoto","fb":"Levothyroxine replaces T4; dose is titrated to normalize TSH.","d":"m"},{"q":"Thyroid storm and myxedema coma differ how on temperature and heart rate?","a":["Storm: hyperthermia + tachycardia; myxedema coma: hypothermia + bradycardia","Both cause hyperthermia and tachycardia","Storm causes hypothermia; myxedema causes fever","Both cause bradycardia"],"c":0,"t":"Thyroid Emergencies","fb":"Thyroid storm (severe hyperthyroidism) = hot and fast; myxedema coma (severe hypothyroidism) = cold and slow.","d":"m"},{"q":"Which are appropriate treatments for THYROID STORM? Select all that apply.","a":["Beta-blockers","PTU or methimazole","Iodine and corticosteroids","IV levothyroxine"],"c":0,"t":"Thyroid Emergencies","fb":"Thyroid storm: beta-blockers, antithyroid drugs, iodine, steroids, cooling. IV levothyroxine treats myxedema coma (the opposite).","d":"m"},{"q":"Match the adrenal cortex zones ('salt, sugar, sex'). Which are correct? Select all that apply.","a":["Zona glomerulosa → aldosterone (salt)","Zona fasciculata → cortisol (sugar)","Zona reticularis → androgens (sex)","Adrenal medulla → aldosterone"],"c":0,"t":"Adrenal Anatomy","fb":"Glomerulosa=aldosterone, fasciculata=cortisol, reticularis=androgens; the medulla makes catecholamines (not aldosterone).","d":"m"},{"q":"Cortisol's major metabolic effects include:","a":["Increased gluconeogenesis, protein catabolism, and immunosuppression","Decreased blood glucose","Enhanced inflammation","Sodium excretion"],"c":0,"t":"Adrenal Anatomy","fb":"Cortisol raises glucose (gluconeogenesis), breaks down protein, and suppresses immune/inflammatory responses.","d":"m"},{"q":"Which features fit CUSHING syndrome (cortisol excess)? Select all that apply.","a":["Central obesity and moon face","Purple striae and thin skin","Hyperglycemia and hypertension","Hyperpigmentation with hypotension"],"c":0,"t":"Cushing & Addison","fb":"Cushing: central obesity, moon face, striae, hyperglycemia, HTN. Hyperpigmentation + hypotension is ADDISON (cortisol deficiency).","d":"m"},{"q":"The MOST common overall cause of Cushing syndrome is:","a":["Exogenous (prescribed) glucocorticoids","A pituitary adenoma","An adrenal tumor","Ectopic ACTH"],"c":0,"t":"Cushing & Addison","fb":"Iatrogenic steroid use is the most common cause; pituitary adenoma (Cushing disease) is the most common endogenous cause.","d":"m"},{"q":"Addison disease (primary adrenal insufficiency) classically presents with:","a":["Fatigue, hypotension, hyperpigmentation, hyponatremia, and hyperkalemia","Central obesity and hypertension","Hyperglycemia and moon face","Heat intolerance and exophthalmos"],"c":0,"t":"Cushing & Addison","fb":"Addison: low cortisol/aldosterone → hypotension, hyponatremia, hyperkalemia, and hyperpigmentation (high ACTH/MSH).","d":"m"},{"q":"Addisonian crisis is treated emergently with:","a":["IV hydrocortisone and fluids","Insulin infusion","Beta-blockers","Methimazole"],"c":0,"t":"Cushing & Addison","fb":"Acute adrenal crisis (shock) requires IV hydrocortisone plus volume resuscitation.","d":"m"},{"q":"Pheochromocytoma is a catecholamine-secreting tumor of the:","a":["Adrenal medulla (chromaffin cells)","Adrenal cortex","Anterior pituitary","Thyroid gland"],"c":0,"t":"Pheochromocytoma","fb":"Pheochromocytoma arises from adrenal medullary chromaffin cells → autonomous epinephrine/norepinephrine.","d":"m"},{"q":"The classic triad of pheochromocytoma is:","a":["Episodic headache, palpitations, and diaphoresis with paroxysmal hypertension","Polyuria, polydipsia, polyphagia","Moon face, striae, and obesity","Fever, headache, neck stiffness"],"c":0,"t":"Pheochromocytoma","fb":"Episodic headache + palpitations + sweating with severe paroxysmal hypertension is classic for pheochromocytoma.","d":"m"},{"q":"In treating pheochromocytoma, the correct blockade sequence is:","a":["Alpha-blockade FIRST (phenoxybenzamine), then beta-blockade","Beta-blockade first, then alpha","Both simultaneously at high dose","Neither — only surgery"],"c":0,"t":"Pheochromocytoma","fb":"Alpha-blockade must precede beta-blockade; unopposed alpha activity from early beta-blockade can cause hypertensive crisis.","d":"m"},{"q":"How does Type 1 diabetes differ from Type 2 in core pathophysiology?","a":["Type 1 = autoimmune beta-cell destruction (absolute insulin deficiency); Type 2 = insulin resistance with relative deficiency","Type 1 = insulin resistance; Type 2 = autoimmune","Both are autoimmune","Neither involves insulin"],"c":0,"t":"Diabetes Mellitus","fb":"T1DM destroys beta cells (no insulin); T2DM is insulin resistance plus a relative insulin deficit.","d":"m"},{"q":"The 'three Ps' of diabetes mellitus are:","a":["Polyuria, polydipsia, polyphagia","Pallor, pain, paresthesia","Ptosis, palpitations, photophobia","Polyuria, pallor, pruritus"],"c":0,"t":"Diabetes Mellitus","fb":"Hyperglycemia above the renal threshold → glucosuria → osmotic diuresis (polyuria) → thirst (polydipsia) and hunger (polyphagia).","d":"m"},{"q":"Which diabetes type is more prone to DKA, and which to HHS?","a":["Type 1 is DKA-prone; Type 2 is more associated with HHS","Type 2 is DKA-prone; Type 1 with HHS","Both equally cause DKA only","Neither causes either"],"c":0,"t":"Diabetes Mellitus","fb":"T1DM (no insulin) → ketosis/DKA; T2DM (some insulin present) → hyperosmolar HHS.","d":"m"},{"q":"Place DKA pathophysiology in order.","a":["Insulin deficiency → counterregulatory hormones → ketogenesis → acidosis & dehydration","Ketogenesis → insulin deficiency → acidosis → counterregulation","Acidosis → dehydration → insulin deficiency → ketogenesis","Counterregulation → acidosis → insulin deficiency → ketogenesis"],"c":0,"t":"DKA","fb":"No insulin → counterregulatory surge → lipolysis/ketogenesis → anion-gap metabolic acidosis and osmotic dehydration.","d":"m"},{"q":"Which findings support DKA? Select all that apply.","a":["Positive urine ketones from increased fat breakdown","Blood glucose elevated from insulin deficiency","Excessive thirst from hyperglycemia-related dehydration","Frequent urination from glucosuria above the renal threshold"],"c":0,"t":"DKA","fb":"All four fit DKA. (Weight LOSS occurs from fluid loss/catabolism — not fluid retention.)","d":"m"},{"q":"Kussmaul respirations and a fruity breath odor in DKA reflect:","a":["Deep rapid breathing to blow off CO2 (respiratory compensation) and exhaled ketones","Airway obstruction","Pulmonary edema","Respiratory alkalosis as the primary problem"],"c":0,"t":"DKA","fb":"The body hyperventilates (Kussmaul) to compensate for metabolic acidosis; acetone gives the fruity breath.","d":"m"},{"q":"How does DKA differ from HHS? Select all that apply.","a":["DKA has strongly positive ketones; HHS has minimal/absent ketones","DKA shows acidosis (low pH/HCO3); HHS pH is near-normal","HHS glucose is typically higher (often > 600) with markedly elevated osmolality","DKA always has higher glucose than HHS"],"c":0,"t":"DKA vs HHS","fb":"DKA = ketoacidosis with moderate hyperglycemia; HHS = extreme hyperglycemia/osmolality with little ketosis. HHS glucose is usually HIGHER.","d":"m"},{"q":"In treating DKA, what is given FIRST?","a":["IV isotonic fluids to restore intravascular volume","IV insulin bolus before fluids","Oral hypoglycemics","Potassium before assessing its level"],"c":0,"t":"DKA Management","fb":"Fluids first to restore volume; insulin and careful potassium management follow.","d":"m"},{"q":"Six hours into DKA treatment, potassium falls from 4.8 to 3.2 mEq/L. Why?","a":["Insulin therapy shifts potassium from the extracellular fluid INTO cells","Ketones increase renal potassium reabsorption","Osmotic diuresis shifts K+ into cells","Acidosis shifts K+ out of cells"],"c":0,"t":"DKA Management","fb":"Insulin drives K+ into cells; despite a normal/high initial level, total body K+ is depleted and can drop fast.","d":"m"},{"q":"During DKA insulin therapy, insulin should be HELD if the serum potassium is:","a":["Below 3.3 mEq/L (replace potassium first)","Above 5.3 mEq/L","Exactly 4.0 mEq/L","Any level — never hold insulin"],"c":0,"t":"DKA Management","fb":"If K+ < 3.3, give potassium before/with insulin to avoid dangerous hypokalemia; replace K+ when < 5.3 during treatment.","d":"m"},{"q":"Insulin belongs to which hormone class?","a":["Peptide","Steroid","Lipid","Mineral"],"c":0,"t":"Hormone Classes","fb":"Insulin is a peptide hormone acting on surface receptors.","d":"e"},{"q":"Most endocrine glands are controlled by ___ feedback.","a":["Negative","Positive","No","Random"],"c":0,"t":"Feedback Regulation","fb":"Negative feedback keeps hormone levels in range.","d":"e"},{"q":"Graves disease causes ___thyroidism.","a":["Hyper","Hypo","Para","Normal"],"c":0,"t":"Graves Disease","fb":"Graves = overactive thyroid (hyperthyroidism).","d":"e"},{"q":"Hashimoto thyroiditis causes ___thyroidism.","a":["Hypo","Hyper","Para","Normal"],"c":0,"t":"Hashimoto","fb":"Hashimoto destroys thyroid tissue → hypothyroidism.","d":"e"},{"q":"Type 1 diabetes is caused by a lack of ___.","a":["Insulin","Glucagon","Cortisol","Thyroid hormone"],"c":0,"t":"Diabetes Mellitus","fb":"T1DM = autoimmune loss of insulin-producing beta cells.","d":"e"},{"q":"The three Ps of diabetes are polyuria, polydipsia, and ___.","a":["Polyphagia","Paralysis","Pallor","Pain"],"c":0,"t":"Diabetes Mellitus","fb":"Polyuria (urination), polydipsia (thirst), polyphagia (hunger).","d":"e"},{"q":"Diabetic ketoacidosis (DKA) is more common in type ___ diabetes.","a":["1","2","3","Both equally"],"c":0,"t":"DKA","fb":"DKA (ketosis) is typical of type 1 diabetes.","d":"e"},{"q":"ADH (antidiuretic hormone) makes the kidneys retain ___.","a":["Water","Sodium","Potassium","Glucose"],"c":0,"t":"ADH / SIADH / DI","fb":"ADH increases water reabsorption → concentrated urine.","d":"e"},{"q":"Cushing syndrome is caused by too much ___.","a":["Cortisol","Insulin","Thyroid hormone","Calcium"],"c":0,"t":"Cushing & Addison","fb":"Cushing = cortisol excess.","d":"e"},{"q":"Addison disease is caused by too ___ cortisol.","a":["Little","Much","Fast","Slow"],"c":0,"t":"Cushing & Addison","fb":"Addison = adrenal insufficiency (low cortisol/aldosterone).","d":"e"},{"q":"Steroid hormones (like cortisol) produce slow, lasting effects because they:","a":["Enter the cell and change gene transcription","Use cell-surface receptors and cAMP","Cannot cross membranes","Act only on blood cells"],"c":0,"t":"Hormone Classes","fb":"Lipid-soluble steroids bind intracellular receptors and alter gene transcription.","d":"m"},{"q":"High circulating thyroid hormone suppresses TSH. This is an example of:","a":["Negative feedback","Positive feedback","Feedforward","Up-regulation"],"c":0,"t":"Feedback Regulation","fb":"Rising end-hormone inhibits its tropic hormone (negative feedback).","d":"m"},{"q":"Labs show HIGH TSH and LOW T4. This indicates:","a":["Primary hypothyroidism (e.g., Hashimoto)","Graves disease","Central hypothyroidism","Normal thyroid"],"c":0,"t":"Endocrine Dysfunction Patterns","fb":"Failing thyroid (low T4) drives a compensatory high TSH = primary hypothyroidism.","d":"m"},{"q":"Labs show LOW TSH and HIGH T4. This indicates:","a":["Primary hyperthyroidism (e.g., Graves)","Primary hypothyroidism","Central hypothyroidism","Iodine deficiency"],"c":0,"t":"Endocrine Dysfunction Patterns","fb":"Autonomous thyroid hormone suppresses TSH = primary hyperthyroidism (Graves).","d":"m"},{"q":"Labs show LOW TSH and LOW T4. The defect is at the level of the:","a":["Pituitary or hypothalamus (central)","Thyroid gland itself","Target-cell receptor","Kidney"],"c":0,"t":"Endocrine Dysfunction Patterns","fb":"Both hormones low together = a central (secondary/tertiary) problem.","d":"m"},{"q":"A patient with small-cell lung cancer has low sodium, low serum osmolality, and concentrated urine. This is:","a":["SIADH (too much ADH)","Diabetes insipidus","Addison disease","Cushing syndrome"],"c":0,"t":"ADH / SIADH / DI","fb":"Excess ADH retains water → dilutional hyponatremia with concentrated urine.","d":"m"},{"q":"A post-neurosurgery patient has high sodium, high serum osmolality, and large volumes of dilute urine. This is:","a":["Central diabetes insipidus","SIADH","Hyperthyroidism","DKA"],"c":0,"t":"ADH / SIADH / DI","fb":"ADH deficiency → free water loss = central DI; treated with desmopressin.","d":"m"},{"q":"A pituitary tumor growing upward classically causes which visual defect?","a":["Bitemporal hemianopia","Total blindness","Tunnel vision","Loss of color only"],"c":0,"t":"Anterior Pituitary","fb":"Compression of the optic chiasm → loss of the temporal (peripheral) visual fields.","d":"m"},{"q":"An adult develops enlarging hands, jaw, and facial features from a growth-hormone-secreting adenoma. This is:","a":["Acromegaly","Gigantism","Dwarfism","Cushing disease"],"c":0,"t":"Anterior Pituitary","fb":"GH excess after growth plates close → acromegaly.","d":"m"},{"q":"A hyperthyroid patient after surgery becomes severely hyperthermic, tachycardic, and agitated. This emergency is:","a":["Thyroid storm","Myxedema coma","Addisonian crisis","DKA"],"c":0,"t":"Thyroid Emergencies","fb":"Severe hyperthyroidism crisis = thyroid storm (hot and fast).","d":"m"},{"q":"A severely hypothyroid patient becomes hypothermic, bradycardic, and stuporous. This emergency is:","a":["Myxedema coma","Thyroid storm","Pheochromocytoma","HHS"],"c":0,"t":"Thyroid Emergencies","fb":"Severe hypothyroidism crisis = myxedema coma (cold and slow).","d":"m"},{"q":"A patient has central obesity, a moon face, purple striae, hyperglycemia, and hypertension. This is:","a":["Cushing syndrome (cortisol excess)","Addison disease","Graves disease","Type 1 diabetes"],"c":0,"t":"Cushing & Addison","fb":"Cortisol excess produces central obesity, moon face, striae, hyperglycemia, and HTN.","d":"m"},{"q":"A patient has fatigue, hypotension, skin hyperpigmentation, low sodium, and high potassium. This is:","a":["Addison disease (adrenal insufficiency)","Cushing syndrome","Pheochromocytoma","Hyperthyroidism"],"c":0,"t":"Cushing & Addison","fb":"Low cortisol/aldosterone → hypotension, hyponatremia, hyperkalemia, hyperpigmentation.","d":"m"},{"q":"A patient has episodic severe hypertension with headache, palpitations, and sweating. When treating the suspected pheochromocytoma, you give:","a":["Alpha-blockade FIRST, then beta-blockade","Beta-blockade first","Insulin first","No medication"],"c":0,"t":"Pheochromocytoma","fb":"Alpha-blockade must precede beta-blockade to avoid unopposed alpha (hypertensive crisis).","d":"m"},{"q":"Which best contrasts type 1 and type 2 diabetes?","a":["Type 1 = autoimmune beta-cell loss (no insulin); Type 2 = insulin resistance","Type 1 = insulin resistance; Type 2 = autoimmune","Both are autoimmune","Neither involves insulin"],"c":0,"t":"Diabetes Mellitus","fb":"T1DM destroys beta cells (absolute deficiency); T2DM is resistance with relative deficiency.","d":"m"},{"q":"A 19-year-old with type 1 diabetes has glucose 420, positive ketones, pH 7.25, and Kussmaul breathing. This is:","a":["Diabetic ketoacidosis (DKA)","Hyperosmolar hyperglycemic state","Hypoglycemia","Thyroid storm"],"c":0,"t":"DKA","fb":"Hyperglycemia + ketones + acidosis + Kussmaul respirations = DKA.","d":"m"},{"q":"Which feature distinguishes HHS from DKA?","a":["HHS has minimal/absent ketones and extremely high glucose/osmolality","HHS has strongly positive ketones","HHS has a very low pH","DKA never has ketones"],"c":0,"t":"DKA vs HHS","fb":"HHS (often type 2/elderly) shows extreme hyperglycemia and osmolality with little ketosis.","d":"m"},{"q":"In treating DKA, the FIRST step is:","a":["IV isotonic fluids to restore volume","An insulin bolus before fluids","Oral hypoglycemics","Potassium without checking a level"],"c":0,"t":"DKA Management","fb":"Fluids first to restore intravascular volume; insulin and potassium follow with monitoring.","d":"m"},{"q":"A few hours into DKA treatment, the potassium drops sharply. The mechanism is:","a":["Insulin drives potassium into cells","Ketones increase potassium reabsorption","Acidosis pushes potassium out of cells","Dehydration raises potassium"],"c":0,"t":"DKA Management","fb":"Insulin shifts K+ intracellularly; total body K+ is already depleted, so it can fall fast.","d":"m"},{"q":"The polyuria and polydipsia of uncontrolled diabetes are caused by:","a":["Glucose exceeding the renal threshold → osmotic diuresis → dehydration → thirst","Excess insulin","Low blood glucose","Sodium retention"],"c":0,"t":"Diabetes Mellitus","fb":"Hyperglycemia spills glucose into urine → osmotic diuresis (polyuria) → thirst (polydipsia).","d":"m"}]}};
